const Header = ({
  apiKeyStatus,
  isCloudReady,
  onHome,
  creatorName,
  appMode,
  tokenUsage = { inputTokens: 0, outputTokens: 0, totalCost: 0 },
  onStartTutorial,
  isAdmin,
  onSignOut,
  user, // Add user prop for super admin check
}) => {
  // Tutorial center state removed - was unused

  // Super Admin check - case-insensitive with trim
  const userEmail = user?.email?.toLowerCase();
  const envSuperAdmin =
    import.meta.env.VITE_SUPER_ADMIN_EMAIL?.trim()?.toLowerCase();
  const isSuperAdmin = userEmail === envSuperAdmin && envSuperAdmin;
  const connectionStatus = useConnectionStatus();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const menuRef = useRef(null);

  // Close mobile menu on ESC key or click outside
  useEffect(() => {
    const handleEsc = (e) => {
      if (e.key === "Escape") setMobileMenuOpen(false);
    };
    const handleClickOutside = (e) => {
      if (menuRef.current && !menuRef.current.contains(e.target)) {
        setMobileMenuOpen(false);
      }
    };
    if (mobileMenuOpen) {
      document.addEventListener("keydown", handleEsc);
      document.addEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("keydown", handleEsc);
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [mobileMenuOpen]);
  const isReview = appMode === "review";
  const isAnalytics = appMode === "analytics";
  const borderColor = isReview
    ? "border-indigo-600"
    : isAnalytics
    ? "border-emerald-600"
    : "border-orange-600";
  const titleColor = isReview
    ? "text-indigo-50"
    : isAnalytics
    ? "text-emerald-50"
    : "text-orange-50";
  const headerBg = isReview
    ? "bg-slate-950 bg-gradient-to-r from-indigo-950/30 to-slate-950"
    : isAnalytics
    ? "bg-slate-950 bg-gradient-to-r from-emerald-950/30 to-slate-950"
    : "bg-slate-950";

  const totalTokens =
    (tokenUsage.inputTokens || 0) + (tokenUsage.outputTokens || 0);
  const formattedTokens =
    totalTokens >= 1000 ? `${(totalTokens / 1000).toFixed(1)}k` : totalTokens;
  const formattedCost = (tokenUsage.totalCost || 0).toFixed(4);

  const getTitle = () => {
    if (isReview) return "Review & Audit Console";
    if (isAnalytics) return "Analytics Dashboard";
    return "UE5 Question Generator";
  };

  const getSubtitle = () => {
    if (isReview) return "Quality Assurance ΓÇó Translation ΓÇó Verification";
    if (isAnalytics)
      return "Generation Metrics ΓÇó Quality Trends ΓÇó URL Validation";
    return "Universal Scenario-Based Generator ΓÇó Official Docs Only";
  };

  const getBadgeStyle = () => {
    if (isReview)
      return "bg-indigo-500/20 text-indigo-300 border-indigo-500/50";
    if (isAnalytics)
      return "bg-emerald-500/20 text-emerald-300 border-emerald-500/50";
    if (appMode === "database")
      return "bg-blue-500/20 text-blue-300 border-blue-500/50";
    return "bg-orange-500/20 text-orange-300 border-orange-500/50";
  };

  const getBadgeText = () => {
    if (isReview) return "REVIEW MODE";
    if (isAnalytics) return "ANALYTICS";
    if (appMode === "database") return "DATABASE VIEW";
    return "CREATE MODE";
  };

  return (
    <header
      className={`${headerBg} text-white p-6 shadow-xl border-b ${borderColor} relative z-20 transition-all duration-500`}
      role="banner"
      aria-label="Application header"
