        {/* Mobile Hamburger Button */}
        <button
          className="lg:hidden flex items-center justify-center w-10 h-10 rounded-lg bg-slate-800 hover:bg-slate-700 transition-colors"
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-expanded={mobileMenuOpen}
          aria-controls="mobile-menu"
          aria-label={mobileMenuOpen ? "Close menu" : "Open menu"}
        >
          <Icon name={mobileMenuOpen ? "x" : "menu"} size={20} />
        </button>
      </div>

      {/* Mobile Menu Dropdown */}
      {mobileMenuOpen && (
        <div
          id="mobile-menu"
          ref={menuRef}
          className="lg:hidden absolute left-0 right-0 top-full bg-slate-900 border-b border-slate-700 shadow-xl z-30 animate-in slide-in-from-top-2 duration-200"
          role="menu"
        >
          <div className="max-w-7xl mx-auto p-4 flex flex-col gap-3 text-xs font-mono">
            {/* Mode Badge */}
            <div className="flex items-center justify-between">
              <span
                className={`flex items-center h-7 px-2.5 rounded text-[11px] font-semibold uppercase tracking-wider border whitespace-nowrap ${getBadgeStyle()}`}
              >
                {getBadgeText()}
              </span>
              {/* Version/Cloud Status */}
              {(() => {
                const { version, isProd } = getVersionDisplay();
                const versionColor = isProd ? "text-red-400" : "text-green-400";
                return (
                  <div className="flex items-center gap-1.5 font-semibold">
                    {isCloudReady ? (
                      <>
                        <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
                        <span className="text-green-400">CLOUD</span>
                      </>
                    ) : (
                      <span className="text-orange-400">LOCAL</span>
                    )}
                    <span className={versionColor}>{version}</span>
                  </div>
                );
              })()}
            </div>

            {/* User Info */}
            {creatorName && (
              <div className="flex items-center justify-between py-2 border-t border-slate-700">
                <div className="flex items-center gap-2 font-medium text-slate-300">
                  <Icon
                    name={isAdmin ? "shield-check" : "user"}
                    size={14}
                    className={isAdmin ? "text-orange-500" : "text-green-500"}
                  />
                  <span>{creatorName}</span>
                  {isAdmin && (
                    <span
                      className={`text-[11px] font-semibold px-1.5 py-0.5 rounded border ${
                        isSuperAdmin
                          ? "bg-purple-900/50 text-purple-400 border-purple-800"
                          : "bg-orange-900/50 text-orange-400 border-orange-800"
                      }`}
                    >
                      {isSuperAdmin ? "SUPER" : "ADMIN"}
                    </span>
                  )}
                </div>
                <button
                  onClick={async () => {
                    setMobileMenuOpen(false);
                    if (onSignOut) onSignOut();
                    await signOutUser();
                  }}
                  className="p-2 text-slate-400 hover:text-red-400 hover:bg-red-900/20 rounded transition-colors"
                  aria-label="Sign out of application"
                >
                  <Icon name="log-out" size={16} />
                </button>
              </div>
            )}

            {/* Tutorial Button */}
            {onStartTutorial &&
              ["create", "review", "database", "analytics"].includes(
                appMode
              ) && (
                <button
                  onClick={() => {
                    setMobileMenuOpen(false);
                    onStartTutorial(appMode);
                  }}
                  className="flex items-center justify-center h-10 gap-2 px-4 text-sm font-bold bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition-all shadow-lg shadow-indigo-900/50"
                >
                  <Icon name="help-circle" size={16} />
                  Start Tutorial
                </button>
              )}

            {/* Stats Row */}
            <div className="flex items-center justify-between py-2 border-t border-slate-700 text-[11px]">
              <div className="flex items-center gap-3">
                {/* Tokens */}
                <div className="flex items-center gap-1 text-purple-400">
                  <Icon name="zap" size={12} />
                  <span className="font-semibold">{formattedTokens}</span>
                  <span className="text-slate-500">tok</span>
                </div>
                {/* Cost */}
                <div className="flex items-center gap-1 text-emerald-400">
                  <span className="text-slate-500">$</span>
                  <span className="font-semibold">{formattedCost}</span>
                </div>
              </div>
              {/* API Status */}
              <span
                className={`font-semibold ${
                  apiKeyStatus.includes("Loaded") ||
                  apiKeyStatus.includes("Auto") ||
                  apiKeyStatus.includes("Cloud")
                    ? "text-green-400"
                    : "text-red-400"
                }`}
              >
                API: {apiKeyStatus}
              </span>
            </div>

            {/* Connection Status (if offline or syncing) */}
            {(!connectionStatus.isOnline ||
              connectionStatus.queuedCount > 0 ||
              connectionStatus.syncInProgress) && (
              <div className="flex items-center gap-3 py-2 border-t border-slate-700">
                {!connectionStatus.isOnline && (
                  <div className="flex items-center gap-1.5 text-yellow-400 font-bold animate-pulse">
                    <Icon name="wifi-off" size={14} />
                    <span>OFFLINE</span>
                  </div>
                )}
                {connectionStatus.queuedCount > 0 && (
                  <div className="flex items-center gap-1 text-orange-400 font-bold">
                    <Icon name="upload-cloud" size={14} />
                    <span>{connectionStatus.queuedCount} queued</span>
                  </div>
                )}
                {connectionStatus.syncInProgress && (
                  <div className="flex items-center gap-1 text-blue-400 font-bold animate-pulse">
                    <Icon
                      name="refresh-cw"
                      size={14}
                      className="animate-spin"
                    />
                    <span>SYNCING</span>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      )}
    </header>
  );
};

export default Header;

import { useState } from "react";
import Icon from "./Icon";
import { sanitizeText } from "../utils/sanitize";

/**
 * Comprehensive Critique Modal - Shows critique + side-by-side improvements
 * Combines AI feedback with visual comparison in one view
 */
const ImprovementModal = ({
  originalQuestion,
  improvedQuestion,
  changesExplanation,
  critiqueText,
  critiqueScore,
  improvedScore, // Score the question would get AFTER applying improvements
  onApply,
  onDismiss,
}) => {
  const [isApplying, setIsApplying] = useState(false);

  const handleApply = async () => {
    setIsApplying(true);
    try {
      await onApply(improvedQuestion);
    } catch (err) {
      console.error("[ImprovementModal] onApply error:", err);
    }
    setIsApplying(false);
  };

  const scoreDelta =
    improvedScore && critiqueScore ? improvedScore - critiqueScore : 0;

  const originalTags = originalQuestion?.tags || [];
  const improvedTags = improvedQuestion?.tags || [];
  const newTags = improvedQuestion
    ? improvedTags.filter((tag) => !originalTags.includes(tag))
    : [];

  return (
    <div className="fixed inset-0 bg-black/80 z-[10000] flex items-start justify-center pt-4 p-4 overflow-y-auto pointer-events-auto">
      <div
        className="bg-slate-900 rounded-xl border-2 border-green-500/50 shadow-2xl max-w-6xl w-full max-h-[90vh] overflow-hidden flex flex-col pointer-events-auto relative"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="bg-gradient-to-r from-green-900/30 to-blue-900/30 border-b border-green-600/30 px-4 py-2">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Icon name="sparkles" size={20} className="text-green-400" />
              <h2 className="text-lg font-bold text-white">AI Critique</h2>
              <span
                className={`px-3 py-1 rounded text-sm font-bold ${
                  critiqueScore >= 90
                    ? "bg-green-600/20 border border-green-500/50 text-green-300"
                    : critiqueScore >= 70
                    ? "bg-yellow-600/20 border border-yellow-500/50 text-yellow-300"
                    : "bg-red-600/20 border border-red-500/50 text-red-300"
                }`}
              >
                Score: {critiqueScore}/100
              </span>
              {scoreDelta > 0 && (
                <span className="px-2 py-1 bg-green-600/20 border border-green-500/50 rounded text-xs font-bold text-green-300">
                  +{scoreDelta} pts improvement
                </span>
              )}
            </div>
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3 scrollbar-thin scrollbar-thumb-slate-600 scrollbar-track-transparent hover:scrollbar-thumb-slate-500">
          {/* AI Critique Feedback */}
          <div className="bg-orange-900/20 border border-orange-700/30 rounded-lg p-3">
            <div className="flex items-start gap-2 mb-2">
              <Icon
                name="message-square"
                size={16}
                className="text-orange-400 mt-0.5 flex-shrink-0"
              />
              <div className="text-xs font-bold text-orange-400 uppercase tracking-wide">
                AI Critique
              </div>
            </div>
            <div className="text-sm text-slate-200 leading-relaxed">
              {critiqueText}
            </div>
          </div>

          {/* Suggested Improvement Section */}
          {changesExplanation && (
            <div>
              <div className="flex items-center gap-2 mb-3">
                <Icon name="zap" size={16} className="text-green-400" />
                <div className="text-sm font-bold text-green-400 uppercase tracking-wide">
                  Suggested Improvement
                </div>
              </div>

              {/* Why Explanation */}
              <div className="bg-blue-900/15 border border-blue-700/30 rounded-lg p-2.5 mb-3">
                <div className="flex items-start gap-2">
                  <Icon
                    name="lightbulb"
                    size={14}
                    className="text-blue-400 mt-0.5 flex-shrink-0"
                  />
                  <div className="text-xs text-slate-200 leading-relaxed">
                    <strong className="text-blue-400">Why:</strong>{" "}
                    {changesExplanation}
                  </div>
                </div>
              </div>

              {/* Column Headers with Scores */}
              <div className="grid grid-cols-2 gap-4 mb-3">
                <div className="flex items-center justify-between px-2">
                  <h3 className="text-xs font-bold text-slate-400 flex items-center gap-1.5 uppercase tracking-wide">
                    <Icon name="file-text" size={14} />
                    Original
                  </h3>
                  <span
                    className={`px-2 py-0.5 rounded text-xs font-bold border ${
                      critiqueScore >= 90
                        ? "bg-green-900/50 border-green-500 text-green-300"
                        : critiqueScore >= 70
                        ? "bg-yellow-900/50 border-yellow-500 text-yellow-300"
                        : "bg-red-900/50 border-red-500 text-red-300"
                    }`}
                  >
                    {critiqueScore}/100
                  </span>
                </div>
                <div className="flex items-center justify-between px-2">
                  <h3 className="text-xs font-bold text-green-400 flex items-center gap-1.5 uppercase tracking-wide">
                    <Icon name="check-circle" size={14} />
                    Improved
                  </h3>
                  {improvedScore ? (
                    <span
                      className={`px-2 py-0.5 rounded text-xs font-bold border ${
                        improvedScore >= 90
                          ? "bg-green-900/50 border-green-500 text-green-300"
                          : improvedScore >= 70
                          ? "bg-yellow-900/50 border-yellow-500 text-yellow-300"
                          : "bg-orange-900/50 border-orange-500 text-orange-300"
                      }`}
                    >
                      {improvedScore}/100
                      {scoreDelta > 0 && (
                        <span className="ml-1 text-green-400">
                          (+{scoreDelta})
                        </span>
                      )}
                    </span>
                  ) : (
                    <span className="px-2 py-0.5 bg-slate-700/50 rounded text-xs text-slate-500 italic">
                      Not scored
                    </span>
                  )}
                </div>
              </div>

              {/* Question Text */}
              <div className="grid grid-cols-2 gap-4 mb-4">
                <div className="bg-slate-800/40 p-3 rounded">
                  <div
                    className="text-sm text-white leading-relaxed"
                    dangerouslySetInnerHTML={sanitizeText(
                      originalQuestion.question
                    )}
                  />
                </div>
                <div className="bg-green-900/20 p-3 rounded border border-green-700/30">
                  <div
                    className="text-sm text-white leading-relaxed"
                    dangerouslySetInnerHTML={sanitizeText(
                      improvedQuestion?.question || originalQuestion.question
                    )}
                  />
                </div>
              </div>

              {/* Answer Options */}
              <div className="text-xs font-bold text-slate-400 uppercase tracking-wide mb-2">
                Answer Options
              </div>
              <div className="space-y-1.5 mb-4">
                {["A", "B", "C", "D"].map((letter) => {
                  const originalOpt =
                    originalQuestion.options?.[letter] ||
                    originalQuestion[`option${letter}`] ||
                    "";
                  const improvedOpt = improvedQuestion
                    ? improvedQuestion.options?.[letter] ||
                      improvedQuestion[`option${letter}`] ||
                      ""
                    : originalOpt; // Fall back to original if no improvement
                  const originalCorrect =
                    originalQuestion.correctLetter === letter ||
                    originalQuestion.correct === letter;
                  const improvedCorrect = improvedQuestion
                    ? improvedQuestion.correctLetter === letter ||
                      improvedQuestion.correct === letter
                    : originalCorrect; // Fall back to original if no improvement

                  return (
                    <div key={letter} className="grid grid-cols-2 gap-4">
                      {/* Original Option */}
                      <div
                        className={`p-2 rounded text-xs border ${
                          originalCorrect
                            ? "bg-green-600/10 border-green-500/40"
                            : "bg-slate-800/40 border-slate-700/40"
                        }`}
                      >
                        <span className="font-bold text-slate-400 mr-1.5">
                          {letter})
                        </span>
                        <span className="text-white">
                          {originalOpt || "(empty)"}
                        </span>
                      </div>

                      {/* Improved Option */}
                      <div
                        className={`p-2 rounded text-xs border ${
                          improvedCorrect
                            ? "bg-green-600/10 border-green-500/40"
                            : "bg-slate-800/40 border-slate-700/40"
                        }`}
                      >
                        <span className="font-bold text-slate-400 mr-1.5">
                          {letter})
                        </span>
                        <span className="text-white">
                          {improvedOpt || "(empty)"}
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Tags */}
              {(originalTags.length > 0 || improvedTags.length > 0) && (
                <div>
                  <div className="text-xs font-bold text-slate-400 uppercase tracking-wide mb-2">
                    Tags
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    {/* Original Tags */}
                    <div className="flex flex-wrap gap-1.5">
                      {originalTags.length > 0 ? (
                        originalTags.map((tag, idx) => (
                          <span
                            key={idx}
                            className="px-2 py-1 bg-slate-700/50 border border-slate-600/50 rounded text-xs text-slate-300"
                          >
                            #{tag}
                          </span>
                        ))
                      ) : (
                        <span className="text-xs text-slate-500 italic">
                          No tags
                        </span>
                      )}
                    </div>

                    {/* Improved Tags */}
                    <div className="flex flex-wrap gap-1.5">
                      {improvedTags.length > 0 ? (
                        improvedTags.map((tag, idx) => {
                          const isNew = newTags.includes(tag);
                          return (
                            <span
                              key={idx}
                              className={`px-2 py-1 rounded text-xs ${
                                isNew
                                  ? "bg-green-600/30 border border-green-500/50 text-green-200"
                                  : "bg-slate-700/50 border border-slate-600/50 text-slate-300"
                              }`}
                            >
                              #{tag}
                            </span>
                          );
                        })
                      ) : (
                        <span className="text-xs text-slate-500 italic">
                          No tags
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="border-t border-slate-700 bg-slate-900/90 px-4 py-2 flex items-center justify-center gap-2.5 relative z-10 pointer-events-auto">
          <div className="flex gap-2.5">
            <button
              onClick={(e) => {
                e.stopPropagation();
                onDismiss();
              }}
              className="px-4 py-1.5 rounded-lg font-bold text-xs bg-slate-800 text-slate-300 hover:bg-slate-700 border border-slate-600 transition-all pointer-events-auto cursor-pointer"
            >
              {changesExplanation ? "Keep Original" : "Close"}
            </button>
            {changesExplanation && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  handleApply();
                }}
                disabled={isApplying}
                className="px-4 py-1.5 rounded-lg font-bold text-xs bg-green-600 text-white hover:bg-green-500 shadow-lg shadow-green-900/50 transition-all disabled:opacity-50 pointer-events-auto cursor-pointer"
              >
                {isApplying ? "Applying..." : "Apply Improvements"}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ImprovementModal;

import Icon from "./Icon";

/**
 * LowScoreWarningModal - Full-screen warning when a question is struggling to pass
 * Shows prominently that the question needs improvement or will be auto-rejected
 */
const LowScoreWarningModal = ({
  score,
  attemptsLeft,
  maxAttempts,
  passingScore,
  onApplyImprovements,
  onDismiss,
  isProcessing = false,
}) => {
  const isLastChance = attemptsLeft === 1;
  const isFinalRejection = attemptsLeft <= 0;

  return (
    <div className="fixed inset-0 bg-black/90 z-50 flex items-center justify-center p-4">
      <div
        className={`max-w-lg w-full rounded-xl border-2 shadow-2xl overflow-hidden ${
          isFinalRejection
            ? "border-red-500 bg-gradient-to-b from-red-950 to-slate-900"
            : isLastChance
            ? "border-orange-500 bg-gradient-to-b from-orange-950 to-slate-900"
            : "border-yellow-500 bg-gradient-to-b from-yellow-950 to-slate-900"
        }`}
      >
        {/* Header */}
        <div
          className={`px-6 py-4 border-b ${
            isFinalRejection
              ? "border-red-700/50 bg-red-900/30"
              : isLastChance
              ? "border-orange-700/50 bg-orange-900/30"
              : "border-yellow-700/50 bg-yellow-900/30"
          }`}
        >
          <div className="flex items-center gap-3">
            <div
              className={`p-2 rounded-full ${
                isFinalRejection
                  ? "bg-red-500/20"
                  : isLastChance
                  ? "bg-orange-500/20"
                  : "bg-yellow-500/20"
              }`}
            >
              <Icon
                name={isFinalRejection ? "x-circle" : "alert-triangle"}
                size={28}
                className={
                  isFinalRejection
                    ? "text-red-400"
                    : isLastChance
                    ? "text-orange-400"
                    : "text-yellow-400"
                }
              />
            </div>
            <div>
              <h2
                className={`text-xl font-bold ${
                  isFinalRejection
                    ? "text-red-300"
                    : isLastChance
                    ? "text-orange-300"
                    : "text-yellow-300"
                }`}
              >
                {isFinalRejection
                  ? "Question Automatically Rejected"
                  : isLastChance
                  ? "Final Attempt Warning!"
                  : "Quality Score Below Threshold"}
              </h2>
              <p className="text-sm text-slate-400">
                {isFinalRejection
                  ? "This question has been rejected due to repeated low scores"
                  : `Score: ${score}/100 (needs ${passingScore}+ to pass)`}
              </p>
            </div>
          </div>
        </div>

        {/* Content */}
        <div className="px-6 py-5 space-y-4">
          {/* Score Display */}
          <div className="flex items-center justify-center gap-4 py-4 bg-slate-800/50 rounded-lg">
            <div className="text-center">
              <div
                className={`text-5xl font-black ${
                  score >= 70
                    ? "text-yellow-400"
                    : score >= 50
                    ? "text-orange-400"
                    : "text-red-400"
                }`}
              >
                {score}
              </div>
              <div className="text-xs text-slate-500 uppercase tracking-wider mt-1">
                Current Score
              </div>
            </div>
            <div className="text-slate-600 text-2xl">ΓåÆ</div>
            <div className="text-center">
              <div className="text-5xl font-black text-green-400">
                {passingScore}+
              </div>
              <div className="text-xs text-slate-500 uppercase tracking-wider mt-1">
                Required
              </div>
            </div>
          </div>

          {/* Warning Message */}
          {!isFinalRejection && (
            <div
              className={`p-4 rounded-lg border ${
                isLastChance
                  ? "bg-red-900/20 border-red-700/50"
                  : "bg-orange-900/20 border-orange-700/50"
              }`}
            >
              <div className="flex items-start gap-3">
                <Icon
                  name="info"
                  size={18}
                  className={
                    isLastChance
                      ? "text-red-400 mt-0.5"
                      : "text-orange-400 mt-0.5"
                  }
                />
                <div className="text-sm">
                  <p
                    className={
                      isLastChance ? "text-red-200" : "text-orange-200"
                    }
                  >
                    {isLastChance ? (
                      <>
                        This is your <strong>LAST CHANCE</strong>. If the score
                        doesn't reach {passingScore}+ after applying
                        improvements, this question will be{" "}
                        <strong>automatically rejected</strong>.
                      </>
                    ) : (
                      <>
                        You have{" "}
                        <strong>
                          {attemptsLeft} attempt{attemptsLeft !== 1 ? "s" : ""}
                        </strong>{" "}
                        left to improve this question above {passingScore}/100
                        before it's automatically rejected.
                      </>
                    )}
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* What to do */}
          {!isFinalRejection && (
            <div className="text-sm text-slate-300">
              <p className="mb-2 font-medium">To improve the score:</p>
              <ul className="list-disc list-inside space-y-1 text-slate-400">
                <li>
                  Click{" "}
                  <strong className="text-green-400">
                    &quot;Apply Improvements&quot;
                  </strong>{" "}
                  to use the AI-suggested fixes
                </li>
                <li>
                  The question will be automatically re-critiqued after applying
                </li>
                <li>Review the improved question carefully before accepting</li>
              </ul>
            </div>
          )}

          {/* Rejection notice */}
          {isFinalRejection && (
            <div className="text-sm text-slate-300 text-center py-2">
              <p>
                This question failed to meet quality standards after{" "}
                {maxAttempts} attempts.
              </p>
              <p className="text-slate-500 mt-1">
                You can regenerate a new question on this topic.
              </p>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-slate-700/50 bg-slate-900/50 flex gap-3 justify-end">
          <button
            onClick={onDismiss}
            className="px-4 py-2 rounded-lg font-medium text-sm bg-slate-800 text-slate-300 hover:bg-slate-700 border border-slate-600 transition-all"
          >
            {isFinalRejection ? "Close" : "Dismiss"}
          </button>
          {!isFinalRejection && (
            <button
              onClick={onApplyImprovements}
              disabled={isProcessing}
              className="px-4 py-2 rounded-lg font-bold text-sm bg-green-600 text-white hover:bg-green-500 shadow-lg shadow-green-900/50 transition-all disabled:opacity-50 flex items-center gap-2"
            >
              <Icon name="zap" size={16} />
              {isProcessing ? "Applying..." : "Apply Improvements"}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default LowScoreWarningModal;

import { Suspense } from "react";
import Icon from "./Icon";
import Sidebar from "./Sidebar";
import AppNavigation from "./AppNavigation";
import ContextToolbar from "./ContextToolbar";
import ViewRouter from "./ViewRouter";
import EmptyState from "./EmptyState";
import ReviewModeBanner from "./ReviewModeBanner";
import { SuspenseSpinner as LoadingSpinner } from "./LoadingSpinner";
import { TARGET_TOTAL, TARGET_PER_CATEGORY } from "../utils/constants";

/**
 * MainLayout Component
 *
 * The main application layout containing:
 * - Sidebar (create mode only)
 * - Main content area with navigation and toolbar
 * - ViewRouter for rendering different modes
 *
 * @param {Object} props - Component props
 *
 * @param {string} props.appMode - Current application mode ('create' | 'review' | 'database' | 'analytics' | 'test')
