import { useEffect, useState } from "react";
import { auth } from "./services/firebase";

/**
 * OmniWatchdog - Development-only HUD for runtime compliance monitoring
 *
 * Features:
 * - ≡ƒ¢í∩╕Å Security Scanner: Detects exposed API keys in DOM
 * - ΓÜí Waterfall Detector: Monitors for sequential fetch calls
 * - ≡ƒæñ Auth State: Shows current user role
 *
 * @returns {null|JSX.Element} HUD component (dev only)
 */
const OmniWatchdog = () => {
  const [alerts, setAlerts] = useState([]);
  const [waterfallWarnings, setWaterfallWarnings] = useState(0);
  const [userRole, setUserRole] = useState("Anonymous");
  const [lastFetchTime, setLastFetchTime] = useState(null);

  // ≡ƒ¢æ Production Safety: Check if we're in development
  const isDev = import.meta.env.DEV;

  useEffect(() => {
    // Don't run in production
    if (!isDev) return;

    // ≡ƒ¢í∩╕Å Security Scanner: Check for exposed API keys
    const scanForLeaks = () => {
      const bodyHTML = document.body.innerHTML;
      const apiKeyPatterns = [
        /AIza[0-9A-Za-z_-]{35}/g, // Google/Gemini/Firebase
        /sk-[a-zA-Z0-9]{48}/g, // OpenAI
        /AKIA[0-9A-Z]{16}/g, // AWS
        /ghp_[a-zA-Z0-9]{36}/g, // GitHub
        /xox[baprs]-[0-9a-zA-Z-]{10,}/g, // Slack
      ];

      const foundLeaks = [];
      apiKeyPatterns.forEach((pattern, index) => {
        const matches = bodyHTML.match(pattern);
        if (matches) {
          const keyType = ["Google/Gemini", "OpenAI", "AWS", "GitHub", "Slack"][
            index
          ];
          foundLeaks.push({
            type: "SECURITY",
            severity: "CRITICAL",
            message: `≡ƒÜ¿ EXPOSED ${keyType} API KEY DETECTED IN DOM!`,
            timestamp: Date.now(),
          });
        }
      });

      if (foundLeaks.length > 0) {
        setAlerts((prev) => [...prev, ...foundLeaks]);
      }
    };

    // Run security scan every 5 seconds
    const securityInterval = setInterval(scanForLeaks, 5000);
    scanForLeaks(); // Initial scan

    // ≡ƒæñ Auth State Monitor
    const unsubscribe = auth.onAuthStateChanged((user) => {
      if (user) {
        // Check if user is admin (you can customize this logic)
        user
          .getIdTokenResult()
          .then((idTokenResult) => {
            const role = idTokenResult.claims.admin ? "Admin" : "User";
            setUserRole(`${role} (${user.email})`);
          })
          .catch(() => {
            setUserRole(`User (${user.email})`);
          });
      } else {
        setUserRole("Anonymous");
      }
    });

    // ΓÜí Waterfall Detector: Monkey-patch fetch
    const originalFetch = window.fetch;
    window.fetch = function (...args) {
      const now = Date.now();

      // Check if this fetch is happening too soon after the last one (< 50ms = likely sequential)
      if (lastFetchTime && now - lastFetchTime < 50) {
        setWaterfallWarnings((prev) => prev + 1);
        setAlerts((prev) => [
          ...prev,
          {
            type: "PERFORMANCE",
            severity: "WARNING",
            message: `≡ƒÉó WATERFALL DETECTED: Sequential fetch to ${args[0]}`,
            timestamp: now,
          },
        ]);
      }

      setLastFetchTime(now);
      return originalFetch.apply(this, args);
    };

    // Cleanup
    return () => {
      clearInterval(securityInterval);
      unsubscribe();
      window.fetch = originalFetch; // Restore original fetch
    };
  }, [isDev, lastFetchTime]);

  // Auto-dismiss alerts after 10 seconds
  useEffect(() => {
    if (!isDev) return;
    if (alerts.length > 0) {
      const timer = setTimeout(() => {
        setAlerts((prev) => prev.slice(1));
      }, 10000);
      return () => clearTimeout(timer);
    }
  }, [isDev, alerts]);

  // Don't render in production
  if (!isDev) return null;

  return (
    <div
      style={{
        position: "fixed",
        top: 0,
        right: 0,
        zIndex: 9999,
        fontFamily: "monospace",
        fontSize: "12px",
        pointerEvents: "none",
      }}
    >
      {/* Auth State Badge */}
      <div
        style={{
          background: userRole.includes("Admin") ? "#10b981" : "#3b82f6",
          color: "white",
          padding: "8px 12px",
          borderRadius: "0 0 0 8px",
          boxShadow: "0 2px 8px rgba(0,0,0,0.2)",
        }}
      >
        ≡ƒæñ {userRole}
      </div>

      {/* Waterfall Counter */}
      {waterfallWarnings > 0 && (
        <div
          style={{
            background: "#f59e0b",
            color: "white",
            padding: "8px 12px",
            marginTop: "4px",
            borderRadius: "0 0 0 8px",
            boxShadow: "0 2px 8px rgba(0,0,0,0.2)",
          }}
        >
          ≡ƒÉó Waterfalls: {waterfallWarnings}
        </div>
      )}

      {/* Alert Stack */}
      <div
        style={{
          position: "fixed",
          top: "50%",
          right: "20px",
          transform: "translateY(-50%)",
          display: "flex",
          flexDirection: "column",
          gap: "8px",
          maxWidth: "400px",
          pointerEvents: "auto",
        }}
      >
        {alerts.slice(-3).map((alert, _index) => (
          <div
            key={alert.timestamp}
            style={{
              background: alert.severity === "CRITICAL" ? "#ef4444" : "#f59e0b",
              color: "white",
              padding: "12px 16px",
              borderRadius: "8px",
              boxShadow: "0 4px 12px rgba(0,0,0,0.3)",
              animation: "slideIn 0.3s ease-out",
              cursor: "pointer",
            }}
            onClick={() =>
              setAlerts((prev) =>
                prev.filter((a) => a.timestamp !== alert.timestamp)
              )
            }
          >
            <div style={{ fontWeight: "bold", marginBottom: "4px" }}>
              {alert.type}
            </div>
            <div>{alert.message}</div>
            <div style={{ fontSize: "10px", opacity: 0.8, marginTop: "4px" }}>
              Click to dismiss
            </div>
          </div>
        ))}
      </div>

      {/* Inline CSS for animations */}
      <style>{`
                @keyframes slideIn {
                    from {
                        transform: translateX(100%);
                        opacity: 0;
                    }
                    to {
                        transform: translateX(0);
                        opacity: 1;
                    }
                }
            `}</style>
    </div>
  );
};

export default OmniWatchdog;

import { useState, useEffect, useCallback } from "react";
import { constructSystemPrompt } from "../services/promptBuilder";
import { generateContentSecure } from "../services/geminiSecure";

import Icon from "./Icon";

const PromptPlayground = ({ config, apiKeyReady, effectiveApiKey }) => {
  // Local state for prompts and parameters
  // Initialize with current config's system prompt
  const [systemPrompt, setSystemPrompt] = useState("");
  const [userPrompt, setUserPrompt] = useState(
    "Generate a set of 3 questions about Nanite in Unreal Engine 5."
  );
  const [temperature, setTemperature] = useState(config.temperature || 0.7);
  const [model, setModel] = useState(config.model || "gemini-2.0-flash");

  // Execution state
  const [output, setOutput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [status, setStatus] = useState("");
  const [error, setError] = useState(null);

  const handleResetToDefaults = useCallback(() => {
    // Construct prompt using current app config
    // We pass empty file context for now as we're testing the core prompt
    const prompt = constructSystemPrompt(config, "");
    setSystemPrompt(prompt);
  }, [config]);

  // Initial load
  useEffect(() => {
    handleResetToDefaults();
  }, [handleResetToDefaults]);

  const handleExecute = async () => {
    if (!import.meta.env.DEV && !apiKeyReady) {
      setError("API Key required");
      return;
    }

    setIsLoading(true);
    setError(null);
    setStatus("Sending request...");
    setOutput("");

    try {
      const result = await generateContentSecure(
        effectiveApiKey,
        systemPrompt,
        userPrompt,
        setStatus,
        temperature,
        model
      );

      setOutput(result);
      setStatus("Complete");
    } catch (err) {
      console.error("Playground error:", err);
      setError(err.message || "Failed to generate content");
      setStatus("Failed");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 text-slate-200">
      {/* Toolbar */}
      <div className="flex items-center justify-between p-4 border-b border-slate-800 bg-slate-900">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-purple-500/20 rounded-lg">
            <Icon name="terminal" className="text-purple-400" size={20} />
          </div>
          <div>
            <h2 className="font-bold text-white">Prompt Playground</h2>
            <p className="text-xs text-slate-400">
              Test and iterate on system prompts
            </p>
          </div>
        </div>

        <div className="flex items-center gap-4">
          {/* Model Selector */}
          <div className="flex items-center gap-2">
            <span className="text-xs text-slate-400 uppercase font-bold">
              Model
            </span>
            <select
              value={model}
              onChange={(e) => setModel(e.target.value)}
              className="bg-slate-950 border border-slate-700 rounded px-2 py-1 text-xs outline-none focus:border-purple-500"
            >
              <option value="gemini-2.0-flash">Gemini 2.0 Flash</option>
              <option value="gemini-1.5-pro">Gemini 1.5 Pro</option>
            </select>
          </div>

          {/* Temperature Slider */}
          <div className="flex items-center gap-2 w-32">
            <span className="text-xs text-slate-400 uppercase font-bold">
              Temp: {temperature}
            </span>
            <input
              type="range"
              min="0"
              max="1"
              step="0.1"
              value={temperature}
              onChange={(e) => setTemperature(parseFloat(e.target.value))}
              className="w-full accent-purple-500 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer"
            />
          </div>

          <button
            onClick={handleResetToDefaults}
            className="px-3 py-1.5 text-xs font-bold text-slate-400 hover:text-white bg-slate-800 hover:bg-slate-700 rounded border border-slate-700 transition-colors flex items-center gap-2"
            title="Reset to current app defaults"
          >
            <Icon name="refresh-cw" size={12} /> Reset
          </button>

          <button
            onClick={handleExecute}
            disabled={isLoading}
            className={`px-4 py-2 text-sm font-bold text-white rounded flex items-center gap-2 transition-all shadow-lg ${
              isLoading
                ? "bg-slate-700 cursor-not-allowed text-slate-500"
                : "bg-purple-600 hover:bg-purple-500 shadow-purple-900/20 hover:scale-105 active:scale-95"
            }`}
          >
            {isLoading ? (
              <Icon name="loader" className="animate-spin" size={16} />
            ) : (
              <Icon name="play" size={16} />
            )}
            {isLoading ? "Running..." : "Run Prompt"}
          </button>
        </div>
      </div>

      {/* Main Content Split View */}
      <div className="flex-1 flex overflow-hidden">
        {/* Left Panel: Inputs */}
        <div className="w-1/2 flex flex-col border-r border-slate-800">
          {/* System Prompt */}
          <div className="flex-1 flex flex-col min-h-0 border-b border-slate-800">
            <div className="px-4 py-2 bg-slate-900/50 flex justify-between items-center">
              <span className="text-xs font-bold text-slate-400 uppercase">
                System Prompt
              </span>
              <span className="text-[10px] text-slate-500 font-mono">
                {systemPrompt.length} chars
              </span>
            </div>
            <textarea
              value={systemPrompt}
              onChange={(e) => setSystemPrompt(e.target.value)}
              className="flex-1 bg-slate-950 p-4 text-xs font-mono text-slate-300 resize-none outline-none focus:bg-slate-900/30 transition-colors"
              spellCheck={false}
              placeholder="Enter system instructions here..."
            />
          </div>

          {/* User Prompt */}
          <div className="h-1/3 flex flex-col min-h-0">
            <div className="px-4 py-2 bg-slate-900/50 flex justify-between items-center border-t border-slate-800">
              <span className="text-xs font-bold text-slate-400 uppercase">
                User Prompt
              </span>
            </div>
            <textarea
              value={userPrompt}
              onChange={(e) => setUserPrompt(e.target.value)}
              className="flex-1 bg-slate-950 p-4 text-sm text-slate-200 resize-none outline-none focus:bg-slate-900/30 transition-colors"
              placeholder="Enter your test input here..."
            />
          </div>
        </div>

        {/* Right Panel: Output */}
        <div className="w-1/2 flex flex-col bg-slate-900/30">
          <div className="px-4 py-2 bg-slate-900/50 flex justify-between items-center border-b border-slate-800">
            <span className="text-xs font-bold text-slate-400 uppercase">
              Model Output
            </span>
            {status && (
              <span className="text-xs text-slate-500 italic">{status}</span>
            )}
          </div>

          <div className="flex-1 overflow-auto p-6">
            {error ? (
              <div className="p-4 bg-red-900/20 border border-red-900/50 rounded-lg text-red-200 text-sm">
                <strong className="block mb-1">Error</strong>
                {error}
              </div>
            ) : output ? (
              <div className="prose prose-invert prose-sm max-w-none">
                <pre className="whitespace-pre-wrap font-mono text-sm text-slate-300">
                  {output}
                </pre>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-600">
                <Icon name="terminal" size={48} className="mb-4 opacity-50" />
                <p className="text-sm">Ready to execute.</p>
                <p className="text-xs mt-2">
                  Configure prompts on the left and click Run.
                </p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PromptPlayground;

