import { useState, useEffect, useCallback, useMemo } from "react";
import Icon from "./Icon";
import {
  generateGUID,
  createSeededRandom,
  seededShuffle,
  reportToSCORM,
} from "../utils/quizUtils";

/**
 * QuizPreview - Simplified interactive quiz component
 *
 * Features:
 * - Balanced difficulty distribution (interleaves Easy/Medium/Hard)
 * - Confidence boost: gives easy question after 2 wrong in a row
 * - Fixed question count and timer
 * - Static A, B, C, D answer display
 */
const QuizPreview = ({ questions, config, onClose }) => {
  // Core quiz state
  const [quizGuid, setQuizGuid] = useState(null); // Unique GUID for this quiz instance
  const [quizQuestions, setQuizQuestions] = useState([]); // Built once at start
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState({}); // Simple: { questionId: "A" }
  const [wrongStreak, setWrongStreak] = useState(0);
  const [showResults, setShowResults] = useState(false);
  const [timeRemaining, setTimeRemaining] = useState(config.timeLimit * 60);
  const [quizStarted, setQuizStarted] = useState(false);
  const [showAnswerWarning, setShowAnswerWarning] = useState(false);
  const [quizStartTime, setQuizStartTime] = useState(null);

  // Accessibility state
  const [focusedOptionIndex, setFocusedOptionIndex] = useState(0);
  const [announceMessage, setAnnounceMessage] = useState("");

  // Derived state - must be before useEffect hooks that use them
  const currentQuestion = quizQuestions[currentIndex];
  const totalQuestions = quizQuestions.length;
  const questionId = currentQuestion?.id || currentQuestion?.uniqueId;
  const selectedAnswer = answers[questionId];
  const isAnswered = selectedAnswer !== undefined;

  /**
   * Build a balanced question list at quiz start
   * Uses seeded randomization for reproducibility
   * Interleaves Easy, Medium, Hard to avoid clustering
   */
  const buildBalancedQuestionList = useCallback(
    (guid) => {
      const randomFn = createSeededRandom(guid);

      // Filter to English-only questions first
      const englishQuestions = questions.filter((q) => {
        const lang = (q.language || "").toLowerCase();
        return lang === "" || lang === "english" || lang === "en";
      });

      const easy = englishQuestions.filter((q) =>
        (q.difficulty || "").toLowerCase().includes("easy")
      );
      const medium = englishQuestions.filter((q) =>
        (q.difficulty || "").toLowerCase().includes("medium")
      );
      const hard = englishQuestions.filter((q) =>
        (q.difficulty || "").toLowerCase().includes("hard")
      );

      // Shuffle each pool using seeded random
      const shuffledEasy = seededShuffle(easy, randomFn);
      const shuffledMedium = seededShuffle(medium, randomFn);
      const shuffledHard = seededShuffle(hard, randomFn);

      // Interleave: E-M-H-E-M-H...
      const distributed = [];
      const maxLen = Math.max(
        shuffledEasy.length,
        shuffledMedium.length,
        shuffledHard.length
      );

      for (let i = 0; i < maxLen; i++) {
        if (shuffledEasy[i]) distributed.push(shuffledEasy[i]);
        if (shuffledMedium[i]) distributed.push(shuffledMedium[i]);
        if (shuffledHard[i]) distributed.push(shuffledHard[i]);
      }

      // Take only what we need
      return distributed.slice(0, config.questionCount || distributed.length);
    },
    [questions, config.questionCount]
  );

  // Generate GUID and build question list when quiz starts
  useEffect(() => {
    if (quizStarted && !quizGuid) {
      const guid = generateGUID();
      setQuizGuid(guid);
      setQuizStartTime(Date.now());
      setQuizQuestions(buildBalancedQuestionList(guid));
      console.log("Quiz started with GUID:", guid);
    }
  }, [quizStarted, quizGuid, buildBalancedQuestionList]);

  // Anti-cheating: Block keyboard shortcuts and track tab visibility
  useEffect(() => {
    if (!quizStarted || showResults) return;

    const handleKeydown = (e) => {
      // Block common cheating shortcuts
      if (
        (e.ctrlKey || e.metaKey) &&
        (e.key === "c" || // Copy
          e.key === "v" || // Paste
          e.key === "f" || // Find
          e.key === "p" || // Print
          e.key === "s") // Save
      ) {
        e.preventDefault();
        console.log("Anti-cheat: Blocked keyboard shortcut");
      }
    };

    const handleCopy = (e) => {
      e.preventDefault();
      console.log("Anti-cheat: Blocked copy attempt");
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        console.log("Anti-cheat: Quiz tab lost focus", {
          quizGuid,
          timestamp: new Date().toISOString(),
          questionIndex: currentIndex,
        });
      }
    };

    document.addEventListener("keydown", handleKeydown);
    document.addEventListener("copy", handleCopy);
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      document.removeEventListener("keydown", handleKeydown);
      document.removeEventListener("copy", handleCopy);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [quizStarted, showResults, quizGuid, currentIndex]);

  // Accessibility: Keyboard navigation for quiz questions
  useEffect(() => {
    if (!quizStarted || showResults || !currentQuestion) return;

    const optionKeys = Object.keys(getOptions(currentQuestion));

    const handleKeyDown = (e) => {
      // Arrow key navigation between options
      if (e.key === "ArrowDown" || e.key === "ArrowRight") {
        e.preventDefault();
        setFocusedOptionIndex((prev) => {
          const newIndex = (prev + 1) % optionKeys.length;
          setAnnounceMessage(
            `Option ${optionKeys[newIndex]}, ${
              optionKeys.length - newIndex
            } of ${optionKeys.length}`
          );
          return newIndex;
        });
      } else if (e.key === "ArrowUp" || e.key === "ArrowLeft") {
        e.preventDefault();
        setFocusedOptionIndex((prev) => {
          const newIndex = prev === 0 ? optionKeys.length - 1 : prev - 1;
          setAnnounceMessage(
            `Option ${optionKeys[newIndex]}, ${newIndex + 1} of ${
              optionKeys.length
            }`
          );
          return newIndex;
        });
      }
      // Enter or Space to select focused option
      else if ((e.key === "Enter" || e.key === " ") && !selectedAnswer) {
        e.preventDefault();
        const selectedKey = optionKeys[focusedOptionIndex];
        handleAnswer(selectedKey);
        setAnnounceMessage(`Selected option ${selectedKey}`);
      }
      // N key for Next Question (when answer is selected)
      else if (e.key === "n" && selectedAnswer) {
        e.preventDefault();
        handleNext();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [
    quizStarted,
    showResults,
    currentQuestion,
    focusedOptionIndex,
    selectedAnswer,
    handleAnswer,
    handleNext,
    getOptions,
  ]);

  // Reset focused option when question changes
  useEffect(() => {
    setFocusedOptionIndex(0);
    if (currentQuestion) {
      setAnnounceMessage(
        `Question ${
          currentIndex + 1
        } of ${totalQuestions}: ${currentQuestion.question.replace(
          /<[^>]*>/g,
          ""
        )}`
      );
    }
  }, [currentIndex, currentQuestion, totalQuestions]);

  // Timer
  useEffect(() => {
    if (!quizStarted || showResults) return;

    const timer = setInterval(() => {
      setTimeRemaining((prev) => {
        if (prev <= 1) {
          setShowResults(true);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [quizStarted, showResults]);

  // Format time display
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  };

  // Handle answer selection
  const handleAnswer = useCallback(
    (selectedKey) => {
      if (!currentQuestion) return;

      const questionId = currentQuestion.id || currentQuestion.uniqueId;
      const isCorrect = selectedKey === currentQuestion.correct;

      // Store just the key
      setAnswers((prev) => ({ ...prev, [questionId]: selectedKey }));

      // Update wrong streak
      if (isCorrect) {
        setWrongStreak(0);
      } else {
        setWrongStreak((prev) => prev + 1);
      }
    },
    [currentQuestion]
  );

  // Handle next question with confidence boost
  const handleNext = useCallback(() => {
    setShowAnswerWarning(false);

    if (currentIndex + 1 >= totalQuestions) {
      setShowResults(true);
      return;
    }

    // Confidence boost: if 2+ wrong in a row, try to give an easy question next
    if (wrongStreak >= 2) {
      const answeredIds = new Set(Object.keys(answers));
      const upcomingQuestions = quizQuestions.slice(currentIndex + 1);

      // Find first easy question in upcoming that hasn't been answered
      const easyIndex = upcomingQuestions.findIndex(
        (q) =>
          (q.difficulty || "").toLowerCase().includes("easy") &&
          !answeredIds.has(q.id || q.uniqueId)
      );

      if (easyIndex > 0) {
        // Swap the easy question to be next
        const newQuestions = [...quizQuestions];
        const easyQ = newQuestions[currentIndex + 1 + easyIndex];
        const nextQ = newQuestions[currentIndex + 1];
        newQuestions[currentIndex + 1] = easyQ;
        newQuestions[currentIndex + 1 + easyIndex] = nextQ;
        setQuizQuestions(newQuestions);
      }
    }

    setCurrentIndex((prev) => prev + 1);
  }, [currentIndex, totalQuestions, wrongStreak, answers, quizQuestions]);

  // Calculate results
  const results = useMemo(() => {
    let correct = 0;
    const total = Object.keys(answers).length;

    quizQuestions.forEach((q) => {
      const qId = q.id || q.uniqueId;
      if (answers[qId] === q.correct) {
        correct++;
      }
    });

    const percentage = total > 0 ? Math.round((correct / total) * 100) : 0;
    const passed = percentage >= config.passingScore;

    return { correct, total, percentage, passed };
  }, [answers, quizQuestions, config.passingScore]);

  // Get options for display (static A, B, C, D - always in order)
  const getOptions = (question) => {
    if (!question?.options) return {};
    return Object.entries(question.options)
      .filter(([, value]) => value)
      .sort(([a], [b]) => a.localeCompare(b)) // Ensure A, B, C, D order
      .reduce((acc, [key, value]) => {
        // Normalize TRUE/FALSE to proper capitalization
        let displayValue = value;
        if (value === "TRUE") displayValue = "True";
        if (value === "FALSE") displayValue = "False";
        acc[key] = displayValue;
        return acc;
      }, {});
  };

  // Report results to SCORM when quiz completes
  useEffect(() => {
    if (showResults && quizGuid && quizStartTime) {
      const timeSpent = Math.floor((Date.now() - quizStartTime) / 1000);
      reportToSCORM(results, quizGuid, timeSpent);
    }
  }, [showResults, results, quizGuid, quizStartTime]);

  // ========== UI RENDERING (unchanged from before) ==========

  // Start screen
  if (!quizStarted) {
    return (
      <div
        className="fixed inset-0 bg-slate-900 z-[9999] flex items-center justify-center p-4 select-none"
        onContextMenu={(e) => e.preventDefault()}
      >
        <div className="max-w-lg w-full text-center">
          <div className="mb-8">
            {/* Unreal Engine Logo */}
            <img
              src="/UE5QuestionGenerator/logos/UE-Secondary-Logo-2023-Horizontal-White.svg"
              alt="Unreal Engine"
              className="h-12 mx-auto mb-6"
            />
            <h2 className="text-2xl font-bold text-white mb-2">
              Assessment Preview
            </h2>
            <p className="text-slate-400">
              Test your knowledge with{" "}
              {config.questionCount || questions.length} questions
            </p>
          </div>

          {/* Quiz info */}
          <div className="bg-slate-800 rounded-lg p-6 mb-8 text-left">
            <div className="space-y-4">
              <div className="flex justify-between items-center">
                <span className="text-slate-400">Questions</span>
                <span className="text-white font-medium">
                  {config.questionCount || questions.length}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-slate-400">Time Limit</span>
                <span className="text-white font-medium">
                  {config.timeLimit} minutes
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-slate-400">Passing Score</span>
                <span className="text-white font-medium">
                  {config.passingScore}%
                </span>
              </div>
            </div>
          </div>

          {/* Instructions */}
          <div
            className="bg-slate-800/50 rounded-lg p-4 mb-8 text-left"
            role="region"
            aria-label="Assessment instructions"
          >
            <h3 className="text-sm font-semibold text-slate-300 mb-3">
              How This Assessment Works
            </h3>
            <ul className="text-sm text-slate-400 space-y-2">
              <li className="flex items-start gap-2">
                <span className="text-blue-400">ΓÇó</span>
                Read each question carefully before selecting your answer
              </li>
              <li className="flex items-start gap-2">
                <span className="text-blue-400">ΓÇó</span>
                Click on your chosen answer to select it
              </li>
              <li className="flex items-start gap-2">
                <span className="text-blue-400">ΓÇó</span>
                Use the &quot;Next Question&quot; button to proceed
              </li>
              <li className="flex items-start gap-2">
                <span className="text-blue-400">ΓÇó</span>
                Keep an eye on the timer in the top right
              </li>
              <li className="flex items-start gap-2">
                <span className="text-blue-400">ΓÇó</span>
                Your results will be shown at the end
              </li>
            </ul>
          </div>

          {/* Actions */}
          <div className="flex gap-4 justify-center">
            <button
              onClick={onClose}
              className="px-6 py-3 bg-slate-700 hover:bg-slate-600 text-white rounded-lg font-medium transition-colors"
            >
              Go Back
            </button>
            <button
              onClick={() => setQuizStarted(true)}
              className="px-8 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-semibold transition-colors"
            >
              Start Assessment
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Results screen
  if (showResults) {
    return (
      <div
        className="fixed inset-0 bg-slate-900 z-[9999] flex items-center justify-center p-4 select-none"
        onContextMenu={(e) => e.preventDefault()}
      >
        <div className="max-w-lg w-full text-center">
          {/* UE Branding */}
          <img
            src="/UE5QuestionGenerator/logos/UE-Secondary-Logo-2023-Horizontal-White.svg"
            alt="Unreal Engine"
            className="h-8 mx-auto mb-8 opacity-60"
          />

          <div
            className={`text-6xl mb-4 ${
              results.passed ? "text-green-400" : "text-red-400"
            }`}
          >
            {results.passed ? (
              <Icon name="check-circle" size={64} className="mx-auto" />
            ) : (
              <Icon name="x-circle" size={64} className="mx-auto" />
            )}
          </div>

          <h2 className="text-2xl font-bold text-white mb-2">
            {results.passed ? "Assessment Passed!" : "Assessment Not Passed"}
          </h2>

          <p className="text-slate-400 mb-8">
            You scored {results.percentage}% ({results.correct} of{" "}
            {results.total} correct)
          </p>

          <div className="bg-slate-800 rounded-lg p-6 mb-8">
            <div className="grid grid-cols-2 gap-4 text-center">
              <div>
                <div className="text-3xl font-bold text-white">
                  {results.correct}
                </div>
                <div className="text-sm text-slate-400">Correct</div>
              </div>
              <div>
                <div className="text-3xl font-bold text-white">
                  {results.total - results.correct}
                </div>
                <div className="text-sm text-slate-400">Incorrect</div>
              </div>
            </div>
          </div>

          <button
            onClick={onClose}
            className="px-8 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-semibold transition-colors"
          >
            Close Preview
          </button>

          <p className="text-xs text-slate-500 mt-6">
            ┬⌐ 2025 Epic Games, Inc. Unreal and its logo are registered
            trademarks.
          </p>
        </div>
      </div>
    );
  }

  // No questions available
  if (!currentQuestion) {
    return (
      <div
        className="fixed inset-0 bg-slate-900 z-[9999] flex items-center justify-center select-none"
        onContextMenu={(e) => e.preventDefault()}
      >
        <div className="bg-slate-800 p-8 rounded-lg text-center max-w-sm">
          <Icon
            name="alert-triangle"
            size={48}
            className="mx-auto text-yellow-500 mb-4"
          />
          <h3 className="text-xl font-bold text-white mb-2">
            No questions available
          </h3>
          <p className="text-slate-400 mb-6">
            There are no questions in the selection.
          </p>
          <button
            onClick={onClose}
            className="px-6 py-2 bg-slate-700 hover:bg-slate-600 text-white rounded font-medium transition-colors"
          >
            Go Back
          </button>
        </div>
      </div>
    );
  }

  const options = getOptions(currentQuestion);

  // Question screen
  return (
    <div
      className="fixed inset-0 bg-slate-900 z-[9999] flex flex-col select-none"
      onContextMenu={(e) => e.preventDefault()}
    >
      {/* Screen reader announcements */}
      <div
        role="status"
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      >
        {announceMessage}
      </div>

      {/* Header */}
      <div className="bg-slate-800 border-b border-slate-700 px-6 py-4">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-4">
            {/* UE Icon */}
            <img
              src="/UE5QuestionGenerator/logos/UE-Icon-2023-White.svg"
              alt="Unreal Engine"
              className="h-6 w-6 opacity-80"
            />
            <span className="text-white font-semibold">
              Question {currentIndex + 1} of {totalQuestions}
            </span>
          </div>

          <div className="flex items-center gap-4">
            <div
              className={`flex items-center gap-2 ${
                timeRemaining < 60 ? "text-red-400" : "text-slate-300"
              }`}
            >
              <Icon name="clock" size={18} />
              <span className="font-mono">{formatTime(timeRemaining)}</span>
            </div>
            <button
              onClick={onClose}
              className="text-slate-400 hover:text-white transition-colors"
              aria-label="Close quiz"
            >
              <Icon name="x" size={24} />
            </button>
          </div>
        </div>
      </div>

      {/* Progress bar */}
      <div
        className="h-1 bg-slate-700"
        role="progressbar"
        aria-valuenow={currentIndex + 1}
        aria-valuemin={1}
        aria-valuemax={totalQuestions}
      >
        <div
          className="h-full bg-blue-500 transition-all duration-300"
          style={{
            width: `${((currentIndex + 1) / totalQuestions) * 100}%`,
          }}
        />
      </div>

      {/* Question content */}
      <div className="flex-1 overflow-auto p-6">
        <div className="max-w-2xl mx-auto">
          {/* Question type badge */}
          <div className="mb-4">
            <span
              className={`px-3 py-1 rounded-full text-xs font-medium ${
                currentQuestion.type === "True/False" ||
                Object.keys(options).length === 2
                  ? "bg-purple-900/50 text-purple-300 border border-purple-700"
                  : "bg-blue-900/50 text-blue-300 border border-blue-700"
              }`}
            >
              {currentQuestion.type === "True/False" ||
              Object.keys(options).length === 2
                ? "Γ£ôΓ£ù True/False"
                : "ΓùÄ Multiple Choice"}
            </span>
          </div>

          <h2
            className="text-xl text-white mb-6 leading-relaxed"
            dangerouslySetInnerHTML={{ __html: currentQuestion.question }}
          />

          {/* Calming instruction */}
          <p className="text-sm text-slate-400 mb-4">
            {currentQuestion.type === "True/False" ||
            Object.keys(options).length === 2
              ? "Select True or False:"
              : "Select the best answer:"}
          </p>

          {/* Keyboard navigation hint */}
          <p className="text-xs text-slate-500 mb-4 italic">
            Use arrow keys to navigate, Enter/Space to select, N for next
            question
          </p>

          {/* Options */}
          <div className="space-y-4" role="listbox" aria-label="Answer options">
            {Object.entries(options).map(([key, text], index) => {
              const isSelected = selectedAnswer === key;
              const isFocused = index === focusedOptionIndex;

              return (
                <button
                  key={key}
                  onClick={() => !isAnswered && handleAnswer(key)}
                  disabled={isAnswered}
                  role="option"
                  aria-selected={isSelected}
                  aria-label={`Option ${key}: ${text}${
                    isSelected ? ", selected" : ""
                  }`}
                  className={`w-full text-left p-4 rounded-lg border-2 transition-all focus:outline-none ${
                    isFocused
                      ? "ring-4 ring-yellow-400 ring-offset-2 ring-offset-slate-900"
                      : ""
                  } ${
                    isSelected
                      ? "border-blue-500 bg-blue-900/30"
                      : "border-slate-600 hover:border-slate-500 bg-slate-800"
                  }`}
                >
                  <div className="flex items-center gap-4">
                    <span
                      className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${
                        isSelected
                          ? "bg-blue-500 text-white"
                          : "bg-slate-700 text-slate-300"
                      }`}
                    >
                      {key}
                    </span>
                    <span
                      className="text-white flex-1"
                      dangerouslySetInnerHTML={{ __html: text }}
                    />
                  </div>
                </button>
              );
            })}
          </div>

          {/* Next button - always visible */}
          <div className="mt-8 text-center">
            {/* Warning message */}
            {!isAnswered && showAnswerWarning && (
              <p className="text-red-400 text-sm mb-3 animate-bounce">
                ΓÜá∩╕Å Please select an answer before continuing
              </p>
            )}
            <button
              onClick={() => {
                if (!isAnswered) {
                  setShowAnswerWarning(true);
                  return;
                }
                handleNext();
              }}
              className={`px-8 py-3 rounded-lg font-semibold transition-colors ${
                isAnswered
                  ? "bg-blue-600 hover:bg-blue-700 text-white"
                  : "bg-slate-700 hover:bg-slate-600 text-slate-300"
              }`}
            >
              {currentIndex + 1 >= totalQuestions
                ? "See Results"
                : "Next Question"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default QuizPreview;

import { useState, useMemo } from "react";
import Icon from "./Icon";
import QuizPreview from "./QuizPreview";
import ScormExportModal from "./ScormExportModal";
import { generateMockQuestions } from "../utils/mockQuestionGenerator";

/**
 * TestView - Admin view for configuring, previewing, and exporting quizzes
 * Allows admins to select approved questions and create assessments
 */
const TestView = ({
  questions = [],
  config: _appConfig,
  isAdmin,
  showMessage,
}) => {
  // Quiz configuration state
  const [quizConfig, setQuizConfig] = useState({
    title: "UE5 Knowledge Assessment",
    description: "Test your Unreal Engine 5 knowledge",
    passingScore: 80,
    timeLimit: 30, // minutes
    questionCount: 10,
    shuffleQuestions: true,
    showFeedback: "end", // "immediate" or "end"
    adaptiveDifficulty: true, // Adjust difficulty based on performance
  });

  // Filter state
  const [filters, setFilters] = useState({
    discipline: "",
  });

  // UI state
  const [showPreview, setShowPreview] = useState(false);
  const [showExport, setShowExport] = useState(false);
  const [selectedQuestionIds, setSelectedQuestionIds] = useState(new Set());
  const [mockQuestions, setMockQuestions] = useState([]);
  const [activeQuizQuestions, setActiveQuizQuestions] = useState([]); // Stabilized questions for preview

  const handleGenerateMockData = () => {
    const mocks = generateMockQuestions();
    setMockQuestions(mocks);
    if (showMessage)
      showMessage(`Generated ${mocks.length} mock questions`, 3000);
  };

  const handleClearMockData = () => {
    setMockQuestions([]);
    setSelectedQuestionIds(new Set());
    if (showMessage) showMessage("Mock data cleared", 2000);
  };

  // Get only approved questions (real + mock)
  const approvedQuestions = useMemo(() => {
    const realApproved = questions.filter((q) => q.status === "accepted");
    return [...realApproved, ...mockQuestions];
  }, [questions, mockQuestions]);

  // Filter approved questions based on criteria
  const filteredQuestions = useMemo(() => {
    return approvedQuestions.filter((q) => {
      if (filters.discipline && q.discipline !== filters.discipline)
        return false;
      return true;
    });
  }, [approvedQuestions, filters]);

  // Get unique disciplines for filter dropdown
  const disciplines = useMemo(() => {
    const set = new Set(approvedQuestions.map((q) => q.discipline));
    return [...set].filter(Boolean).sort();
  }, [approvedQuestions]);

  // Get selected questions for preview/export
  const selectedQuestions = useMemo(() => {
    if (selectedQuestionIds.size === 0) {
      // If none selected, use filtered questions up to questionCount
      const shuffled = quizConfig.shuffleQuestions
        ? [...filteredQuestions].sort(() => Math.random() - 0.5)
        : filteredQuestions;
      return shuffled.slice(0, quizConfig.questionCount);
    }
    return filteredQuestions.filter((q) =>
      selectedQuestionIds.has(q.id || q.uniqueId)
    );
  }, [filteredQuestions, selectedQuestionIds, quizConfig]);

  // Toggle question selection
  const toggleQuestion = (q) => {
    const id = q.id || q.uniqueId;
    setSelectedQuestionIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };

  // Select all / deselect all
  const toggleSelectAll = () => {
    if (selectedQuestionIds.size === filteredQuestions.length) {
      setSelectedQuestionIds(new Set());
    } else {
      setSelectedQuestionIds(
        new Set(filteredQuestions.map((q) => q.id || q.uniqueId))
      );
    }
  };

  // Snapshot questions when starting preview to prevent re-shuffling during quiz
  const handleStartPreview = () => {
    setActiveQuizQuestions([...selectedQuestions]);
    setShowPreview(true);
  };

  if (!isAdmin) {
    return (
      <div className="flex items-center justify-center h-64 text-slate-400">
        <div className="text-center">
          <Icon name="lock" size={48} className="mx-auto mb-4 opacity-50" />
          <p>Admin access required</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-6xl mx-auto">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-white flex items-center gap-3">
          <Icon name="clipboard-list" size={28} />
          Test Configuration
        </h1>
        <div className="flex justify-between items-center mt-2">
          <p className="text-slate-400">
            Configure and preview quizzes from approved questions
          </p>
          <div className="flex gap-2">
            {mockQuestions.length === 0 && (
              <button
                onClick={handleGenerateMockData}
                className="text-xs text-indigo-400 hover:text-indigo-300 border border-indigo-900/50 bg-indigo-900/20 px-3 py-1 rounded flex items-center gap-1"
              >
                <Icon name="wand" size={12} />
                Generate Mock Data
              </button>
            )}
            {mockQuestions.length > 0 && (
              <button
                onClick={handleClearMockData}
                className="text-xs text-red-400 hover:text-red-300 border border-red-900/50 bg-red-900/20 px-3 py-1 rounded"
              >
                Clear Mock Data ({mockQuestions.length})
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left: Quiz Settings */}
        <div className="lg:col-span-1 space-y-6">
          {/* Quiz Config Card */}
          <div className="bg-slate-800 rounded-lg border border-slate-700 p-5">
            <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
              <Icon name="settings" size={18} />
              Quiz Settings
            </h2>

            {/* Title */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-slate-300 mb-1">
                Quiz Title
              </label>
              <input
                type="text"
                value={quizConfig.title}
                onChange={(e) =>
                  setQuizConfig({ ...quizConfig, title: e.target.value })
                }
                className="w-full px-3 py-2 bg-slate-900 border border-slate-600 rounded text-white focus:border-blue-500 outline-none"
              />
            </div>

            {/* Passing Score */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-slate-300 mb-1">
                Passing Score: {quizConfig.passingScore}%
              </label>
              <input
                type="range"
                min="50"
                max="100"
                step="5"
                value={quizConfig.passingScore}
                onChange={(e) =>
                  setQuizConfig({
                    ...quizConfig,
                    passingScore: parseInt(e.target.value),
                  })
                }
                className="w-full"
              />
            </div>

            {/* Time Limit */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-slate-300 mb-1">
                Time Limit
              </label>
              <select
                value={quizConfig.timeLimit}
                onChange={(e) =>
                  setQuizConfig({
                    ...quizConfig,
                    timeLimit: parseInt(e.target.value),
                  })
                }
                className="w-full px-3 py-2 bg-slate-900 border border-slate-600 rounded text-white"
              >
                <option value={10}>10 minutes</option>
                <option value={15}>15 minutes</option>
                <option value={30}>30 minutes</option>
                <option value={45}>45 minutes</option>
                <option value={60}>60 minutes</option>
                <option value={90}>90 minutes</option>
              </select>
            </div>

            {/* Question Count */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-slate-300 mb-1">
                Questions: {quizConfig.questionCount}
              </label>
              <input
                type="range"
                min="5"
                max={Math.min(50, filteredQuestions.length || 50)}
                value={Math.min(
                  quizConfig.questionCount,
                  filteredQuestions.length
                )}
                onChange={(e) =>
                  setQuizConfig({
                    ...quizConfig,
                    questionCount: parseInt(e.target.value),
                  })
                }
                className="w-full"
              />
            </div>

            {/* Shuffle */}
            <div className="mb-4">
              <label className="flex items-center gap-2 text-sm text-slate-300 cursor-pointer">
                <input
                  type="checkbox"
                  checked={quizConfig.shuffleQuestions}
                  onChange={(e) =>
                    setQuizConfig({
                      ...quizConfig,
                      shuffleQuestions: e.target.checked,
                    })
                  }
                  className="rounded border-slate-600"
                />
                Shuffle question order
              </label>
            </div>

            {/* Feedback Mode */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-slate-300 mb-1">
                Show Feedback
              </label>
              <select
                value={quizConfig.showFeedback}
                onChange={(e) =>
                  setQuizConfig({ ...quizConfig, showFeedback: e.target.value })
                }
                className="w-full px-3 py-2 bg-slate-900 border border-slate-600 rounded text-white"
              >
                <option value="immediate">After each question</option>
                <option value="end">At quiz end</option>
              </select>
            </div>

            {/* Adaptive Difficulty */}
            <div className="mb-4">
              <label className="flex items-center gap-2 text-sm text-slate-300 cursor-pointer">
                <input
                  type="checkbox"
                  checked={quizConfig.adaptiveDifficulty}
                  onChange={(e) =>
                    setQuizConfig({
                      ...quizConfig,
                      adaptiveDifficulty: e.target.checked,
                    })
                  }
                  className="rounded border-slate-600"
                />
                Adaptive difficulty
              </label>
              <p className="text-xs text-slate-500 mt-1 ml-6">
                Adjusts question difficulty based on performance
              </p>
            </div>
          </div>

          {/* Filter Card */}
          <div className="bg-slate-800 rounded-lg border border-slate-700 p-5">
            <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
              <Icon name="filter" size={18} />
              Question Filters
            </h2>

            {/* Discipline */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-slate-300 mb-1">
                Discipline
              </label>
              <select
                value={filters.discipline}
                onChange={(e) =>
                  setFilters({ ...filters, discipline: e.target.value })
                }
                className="w-full px-3 py-2 bg-slate-900 border border-slate-600 rounded text-white"
              >
                <option value="">All Disciplines</option>
                {disciplines.map((d) => (
                  <option key={d} value={d}>
                    {d}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="space-y-3">
            <button
              onClick={handleStartPreview}
              disabled={selectedQuestions.length === 0}
              className="w-full px-4 py-3 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-700 disabled:text-slate-500 text-white rounded-lg font-semibold transition-colors flex items-center justify-center gap-2"
            >
              <Icon name="play" size={18} />
              Preview Quiz ({selectedQuestions.length} questions)
            </button>

            <button
              onClick={() => setShowExport(true)}
              disabled={selectedQuestions.length === 0}
              className="w-full px-4 py-3 bg-green-600 hover:bg-green-700 disabled:bg-slate-700 disabled:text-slate-500 text-white rounded-lg font-semibold transition-colors flex items-center justify-center gap-2"
            >
              <Icon name="download" size={18} />
              Export SCORM Package
            </button>
          </div>
        </div>

        {/* Right: Question List */}
        <div className="lg:col-span-2">
          <div className="bg-slate-800 rounded-lg border border-slate-700">
            <div className="p-4 border-b border-slate-700 flex items-center justify-between">
              <h2 className="text-lg font-semibold text-white">
                Available Questions ({filteredQuestions.length})
              </h2>
              <button
                onClick={toggleSelectAll}
                className="text-sm text-blue-400 hover:text-blue-300"
              >
                {selectedQuestionIds.size === filteredQuestions.length
                  ? "Deselect All"
                  : "Select All"}
              </button>
            </div>

            <div className="h-[calc(100vh-280px)] min-h-[600px] overflow-y-auto">
              {filteredQuestions.length === 0 ? (
                <div className="p-8 text-center text-slate-400">
                  <Icon
                    name="inbox"
                    size={48}
                    className="mx-auto mb-4 opacity-50"
                  />
                  <p>No approved questions match your filters</p>
                  {filters.discipline === "" && (
                    <button
                      onClick={handleGenerateMockData}
                      className="mt-4 px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded text-sm font-bold transition-all flex items-center gap-2 mx-auto"
                    >
                      <Icon name="wand" size={16} />
                      Generate Mock Data
                    </button>
                  )}
                </div>
              ) : (
                <div className="divide-y divide-slate-700">
                  {filteredQuestions.map((q) => {
                    const id = q.id || q.uniqueId;
                    const isSelected = selectedQuestionIds.has(id);
                    return (
                      <div
                        key={id}
                        onClick={() => toggleQuestion(q)}
                        className={`p-4 cursor-pointer hover:bg-slate-700/50 transition-colors ${
                          isSelected ? "bg-blue-900/20" : ""
                        }`}
                      >
                        <div className="flex items-start gap-3">
                          <input
                            type="checkbox"
                            checked={isSelected}
                            onChange={() => toggleQuestion(q)}
                            className="mt-1 rounded border-slate-600"
                          />
                          <div className="flex-1 min-w-0">
                            <p className="text-white text-sm line-clamp-2">
                              {q.question}
                            </p>
                            <div className="flex gap-2 mt-2">
                              <span className="text-xs px-2 py-0.5 bg-slate-700 text-slate-300 rounded">
                                {q.discipline}
                              </span>
                              <span className="text-xs px-2 py-0.5 bg-slate-700 text-slate-300 rounded">
                                {q.difficulty}
                              </span>
                              <span className="text-xs px-2 py-0.5 bg-slate-700 text-slate-300 rounded">
                                {q.type}
                              </span>
                            </div>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Quiz Preview Modal */}
      {showPreview && (
        <QuizPreview
          questions={activeQuizQuestions}
          config={quizConfig}
          onClose={() => {
            setShowPreview(false);
            setActiveQuizQuestions([]);
          }}
        />
      )}

      {/* SCORM Export Modal */}
      {showExport && (
        <ScormExportModal
          questions={selectedQuestions}
          onClose={() => setShowExport(false)}
        />
      )}
    </div>
  );
};

export default TestView;

import React from "react";
import { Suspense } from "react";
import Icon from "./Icon";
import { SuspenseSpinner as LoadingSpinner } from "./LoadingSpinner";
// Lazy load heavy views - most views are lazy for better navigation perf
const AnalyticsView = React.lazy(() => import("./AnalyticsView"));
const DatabaseView = React.lazy(() => import("./DatabaseView"));
// ReviewMode is eagerly loaded to prevent remount issues with edit locks
import ReviewMode from "./ReviewMode";
const TestView = React.lazy(() => import("./TestView"));
const PromptPlayground = React.lazy(() => import("./PromptPlayground"));
const AdminPanel = React.lazy(() => import("./AdminPanel"));
import QuestionList from "./QuestionList";

/**
 * EmptyReviewState - Illustrated empty state with CTA
 * Guides users to generate questions when Review is empty
 */
const EmptyReviewState = ({
  onNavigateToCreate,
  hasQuestionsInOtherFilters = false,
  isAdmin = false,
}) => (
  <div className="flex flex-col items-center justify-center h-full py-16 px-8">
    {/* Illustration */}
    <div className="relative mb-8">
      <div className="w-24 h-24 bg-gradient-to-br from-indigo-500/20 to-purple-500/20 rounded-full flex items-center justify-center">
        <Icon name="clipboard-list" size={48} className="text-indigo-400" />
      </div>
      <div className="absolute -bottom-2 -right-2 w-10 h-10 bg-orange-500/20 rounded-full flex items-center justify-center animate-bounce">
        <Icon name="sparkles" size={20} className="text-orange-400" />
      </div>
    </div>

    {/* Message */}
    <h3 className="text-xl font-bold text-white mb-2">
      {hasQuestionsInOtherFilters ? "No Pending Questions" : "Ready to Review"}
    </h3>
    <p className="text-slate-400 text-center max-w-md mb-6">
      {hasQuestionsInOtherFilters
        ? "All questions in this filter have been reviewed! Check other filters or generate more."
        : isAdmin
        ? "Generate your first batch of questions to start reviewing and approving them for your assessments."
        : "No questions are pending review. Ask an administrator to generate more questions."}
    </p>

    {/* CTA Button - Admin only */}
    {isAdmin && (
      <button
        onClick={onNavigateToCreate}
