    {/* Keyboard shortcut hint - Admin only */}
    {isAdmin && (
      <p className="text-xs text-slate-600 mt-4">
        or press{" "}
        <kbd className="px-1.5 py-0.5 bg-slate-800 rounded text-slate-400 font-mono">
          Ctrl
        </kbd>{" "}
        +{" "}
        <kbd className="px-1.5 py-0.5 bg-slate-800 rounded text-slate-400 font-mono">
          Enter
        </kbd>{" "}
        in Create mode
      </p>
    )}
  </div>
);

const ViewRouter = ({
  appMode,
  uniqueFilteredQuestions,
  databaseQuestions,

  config,
  effectiveApiKey,
  isAdmin,
  isProcessing,
  handlers,
  state,
  setters,
  onNavigateToCreate, // callback to switch to Create mode
  onNavigateHome, // callback to go back to landing page
  onStartTutorial, // callback to start tutorial scenario
  allQuestionsMap, // all questions for analytics
}) => {
  const {
    handleLoadFromSheets,
    handleLoadFromFirestore,
    handleUpdateDatabaseQuestion,
    handleKickBackToReview,
    handleUpdateStatus,
    handleExplain,
    handleVariate,
    handleCritique,
    handleApplyRewrite,
    handleTranslateSingle,
    handleLanguageSwitch,
    handleDelete,
    handleManualUpdate,
  } = handlers;

  const {
    currentReviewIndex,
    translationMap,
    filterByCreator,
    filteredQuestions,
    questions,
    status,
    userRole, // NEW
  } = state;
  const {
    setDatabaseQuestions,
    setCurrentReviewIndex,
    setFilterByCreator,
    showMessage,
  } = setters;

  return (
    <Suspense fallback={<LoadingSpinner />}>
      {appMode === "analytics" ? (
        <AnalyticsView
          onBack={onNavigateHome}
          onStartTutorial={() => onStartTutorial("analytics")}
          allQuestionsMap={allQuestionsMap}
        />
      ) : appMode === "database" ? (
        <DatabaseView
          questions={databaseQuestions}
          sheetUrl={config.sheetUrl}
          onLoad={handleLoadFromSheets}
          onLoadFirestore={handleLoadFromFirestore}
          onClearView={() => setDatabaseQuestions([])}
          onHardReset={() => setDatabaseQuestions([])}
          onUpdateQuestion={handleUpdateDatabaseQuestion}
          onKickBack={handleKickBackToReview}
          isProcessing={isProcessing}
          showMessage={showMessage}
          filterMode={state.filterMode}
          sortBy={state.sortBy}
          searchTerm={state.searchTerm}
          onStartTutorial={() => onStartTutorial("database")}
          isAdmin={isAdmin}
          userRole={userRole}
        />
      ) : appMode === "test" && isAdmin ? (
        <TestView
          questions={[...questions, ...databaseQuestions]}
          config={config}
          isAdmin={isAdmin}
          showMessage={showMessage}
        />
      ) : appMode === "playground" && isAdmin ? (
        <PromptPlayground
          config={config}
          apiKeyReady={!!effectiveApiKey}
          effectiveApiKey={effectiveApiKey}
        />
      ) : appMode === "admin" && isAdmin ? (
        <AdminPanel
          showMessage={showMessage}
          config={config}
          handleChange={handlers.handleConfigChange}
          showApiKey={state.showApiKey}
          setShowApiKey={setters.setShowApiKey}
          files={state.files}
          handleDetectTopics={handlers.handleDetectTopics}
          isDetecting={state.isDetecting}
          fileInputRef={state.fileInputRef}
          handleFileChange={handlers.handleFileChange}
          removeFile={handlers.removeFile}
          isApiReady={!!effectiveApiKey}
          customTags={state.customTags}
          onSaveCustomTags={handlers.handleSaveCustomTags}
          currentUser={state.currentUser}
        />
      ) : appMode === "review" && uniqueFilteredQuestions.length > 0 ? (
        <ReviewMode
          questions={uniqueFilteredQuestions}
          currentIndex={currentReviewIndex}
          setCurrentIndex={setCurrentReviewIndex}
          onUpdateStatus={handleUpdateStatus}
          onExplain={handleExplain}
          onVariate={handleVariate}
          onCritique={handleCritique}
          onApplyRewrite={handleApplyRewrite}
          onTranslateSingle={handleTranslateSingle}
          onSwitchLanguage={handleLanguageSwitch}
          onDelete={handleDelete}
          onUpdateQuestion={handleManualUpdate}
          translationMap={translationMap}
          onStartTutorial={() => onStartTutorial("review")}
          onKickBack={handleKickBackToReview}
          userRole={userRole} // NEW
        />
      ) : appMode === "review" && uniqueFilteredQuestions.length === 0 ? (
        /* NEW: Empty state for Review mode with CTA */
        <EmptyReviewState
          onNavigateToCreate={onNavigateToCreate}
          hasQuestionsInOtherFilters={
            filteredQuestions.length > 0 || questions.length > 0
          }
          isAdmin={isAdmin}
        />
      ) : (
        <>
          <QuestionList
            questions={uniqueFilteredQuestions}
            translationMap={translationMap}
            appMode={appMode}
            isProcessing={isProcessing}
            onUpdateStatus={handleUpdateStatus}
            onExplain={handleExplain}
            onVariate={handleVariate}
            onCritique={handleCritique}
            onApplyRewrite={handleApplyRewrite}
            onTranslateSingle={handleTranslateSingle}
            onSwitchLanguage={handleLanguageSwitch}
            onDelete={handleDelete}
            onUpdateQuestion={handleManualUpdate}
            showMessage={showMessage}
            userRole={userRole} // NEW
          />
        </>
      )}

      {uniqueFilteredQuestions.length === 0 &&
        filteredQuestions.length > 0 &&
        appMode !== "review" && (
          <div className="flex flex-col items-center justify-center h-full text-slate-600 pt-10">
            <Icon name="filter" size={32} className="mb-3 text-slate-800" />
            <p className="font-medium text-slate-500">
              No questions match current filters.
            </p>
            {filterByCreator && (
              <p className="text-xs text-slate-600 mt-2">
                Filtering by Creator:{" "}
                <span className="text-blue-500 font-bold">
                  {config.creatorName}
                </span>
                .
                <button
                  onClick={() => setFilterByCreator(false)}
                  className="ml-2 underline hover:text-blue-400"
                >
                  Show All Creators?
                </button>
              </p>
            )}
          </div>
        )}

      {!state.showHistory &&
        uniqueFilteredQuestions.length === 0 &&
        questions.length === 0 &&
        !status &&
        appMode === "create" && (
          <div className="flex flex-col items-center justify-center h-full text-slate-600">
            <Icon name="terminal" size={48} className="mb-4 text-slate-800" />
            <p className="font-medium text-slate-500">
              Ready. Click 'GENERATE QUESTIONS' to begin or upload a source
              file.
            </p>
          </div>
        )}
    </Suspense>
  );
};

export default ViewRouter;

import Icon from "../Icon";
import { CATEGORY_KEYS } from "../../utils/constants";

// Difficulty colors (shared with parent)
const DIFFICULTY_COLORS = {
  "Easy MC": "#22c55e",
  "Easy T/F": "#4ade80",
  "Medium MC": "#eab308",
  "Medium T/F": "#facc15",
  "Hard MC": "#ef4444",
  "Hard T/F": "#f87171",
};

// Helper to get quality color (avoids nested ternary)
const getQualityColor = (score) => {
  if (!score) return "#64748b";
  if (score >= 70) return "#22c55e";
  if (score >= 50) return "#eab308";
  return "#ef4444";
};

/**
 * DisciplineDetailPanel - Shows detailed breakdown when a discipline card is clicked
 * @param {Object} props
 * @param {string} props.discipline - Discipline name
 * @param {Array} props.questions - All questions array
 * @param {string} props.color - Discipline color
 * @param {Function} props.onClose - Close handler
 */
const DisciplineDetailPanel = ({ discipline, questions, color, onClose }) => {
  const disciplineQuestions = questions.filter(
    (q) => q.discipline === discipline
  );

  // Difficulty breakdown for this discipline
  const difficultyBreakdown = CATEGORY_KEYS.map((key) => ({
    name: key.replace(" MC", "\nMC").replace(" T/F", "\nT/F"),
    shortName: key,
    value: disciplineQuestions.filter((q) => q.difficulty === key).length,
    fill: DIFFICULTY_COLORS[key],
  })).filter((d) => d.value > 0);

  // Status breakdown
  const accepted = disciplineQuestions.filter(
    (q) => q.status === "accepted"
  ).length;
  const pending = disciplineQuestions.filter(
    (q) => !q.status || q.status === "pending"
  ).length;
  const rejected = disciplineQuestions.filter(
    (q) => q.status === "rejected"
  ).length;

  // Average quality
  const withScores = disciplineQuestions.filter((q) => q.critiqueScore != null);
  const avgQuality =
    withScores.length > 0
      ? Math.round(
          withScores.reduce((sum, q) => sum + q.critiqueScore, 0) /
            withScores.length
        )
      : null;

  return (
    <div
      className="bg-slate-900 border-2 rounded-xl p-6 animate-in slide-in-from-top-2 duration-200"
      style={{ borderColor: color }}
    >
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div
            className="w-4 h-4 rounded-full"
            style={{ backgroundColor: color }}
          />
          <h3 className="text-lg font-bold text-white">{discipline}</h3>
          <span className="text-sm text-slate-400">
            ({disciplineQuestions.length} questions)
          </span>
        </div>
        <button
          onClick={onClose}
          className="p-1 hover:bg-slate-800 rounded transition-colors"
        >
          <Icon name="x" size={18} className="text-slate-400" />
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Difficulty Breakdown */}
        <div>
          <h4 className="text-sm font-medium text-slate-400 mb-3">
            Difficulty Breakdown
          </h4>
          {difficultyBreakdown.length > 0 ? (
            <div className="space-y-2">
              {difficultyBreakdown.map((d) => (
                <div key={d.shortName} className="flex items-center gap-2">
                  <div
                    className="w-2 h-2 rounded-full"
                    style={{ backgroundColor: d.fill }}
                  />
                  <span className="text-xs text-slate-300 flex-1">
                    {d.shortName}
                  </span>
                  <span className="text-sm font-bold text-white">
                    {d.value}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-xs text-slate-500">No questions yet</p>
          )}
        </div>

        {/* Status Distribution */}
        <div>
          <h4 className="text-sm font-medium text-slate-400 mb-3">Status</h4>
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-green-500" />
              <span className="text-xs text-slate-300 flex-1">Accepted</span>
              <span className="text-sm font-bold text-green-400">
                {accepted}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-amber-500" />
              <span className="text-xs text-slate-300 flex-1">Pending</span>
              <span className="text-sm font-bold text-amber-400">
                {pending}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-red-500" />
              <span className="text-xs text-slate-300 flex-1">Rejected</span>
              <span className="text-sm font-bold text-red-400">{rejected}</span>
            </div>
          </div>
        </div>

        {/* Quality Stats */}
        <div>
          <h4 className="text-sm font-medium text-slate-400 mb-3">Quality</h4>
          <div className="flex items-baseline gap-2">
            <span
              className="text-3xl font-bold"
              style={{
                color: avgQuality
                  ? avgQuality >= 70
                    ? "#22c55e"
                    : avgQuality >= 50
                    ? "#eab308"
                    : "#ef4444"
                  : "#64748b",
              }}
            >
              {avgQuality ?? "ΓÇö"}
            </span>
            <span className="text-xs text-slate-500">avg score</span>
          </div>
          <p className="text-xs text-slate-500 mt-2">
            {withScores.length} of {disciplineQuestions.length} critiqued
          </p>
          {disciplineQuestions.length > 0 && (
            <div className="mt-3 h-2 bg-slate-800 rounded-full overflow-hidden">
              <div
                className="h-full bg-green-500 transition-all"
                style={{
                  width: `${(accepted / disciplineQuestions.length) * 100}%`,
                }}
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default DisciplineDetailPanel;

import { useState, useEffect } from "react";
import Icon from "../Icon";
import CooldownTimer from "../CooldownTimer";
import {
  subscribeToRateLimitState,
  getRateLimitStatus,
} from "../../utils/rateLimitState";

/**
 * ActionFooter - Generate button with live progress indicator
 * Shows animated progress bar and status text during generation
 */
const ActionFooter = ({
  handleGenerate,
  isGenerating,
  isTargetMet,
  maxBatchSize,
  isApiReady,
  handleBulkTranslateMissing,
  isProcessing,
  allQuestionsMap,
  status = "", // Live status text from useGeneration hook
}) => {
  // Subscribe to rate limit state for cooldown display
  const [rateLimitStatus, setRateLimitStatus] = useState(getRateLimitStatus());

  useEffect(() => {
    const unsubscribe = subscribeToRateLimitState(setRateLimitStatus);
    return unsubscribe;
  }, []);

  const isRateLimited =
    rateLimitStatus.isLimited && rateLimitStatus.remainingSeconds > 0;

  return (
    <div className="sticky bottom-0 bg-slate-950 pt-4 pb-2 border-t border-slate-800 z-20 -mx-6 px-6 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.3)]">
      <div className="space-y-3">
        {/* Rate Limit Cooldown Timer */}
        {isRateLimited && (
          <CooldownTimer
            remainingSeconds={rateLimitStatus.remainingSeconds}
            isLimited={true}
          />
        )}

        {/* Progress Indicator - shown during generation */}
        {isGenerating && (
          <div className="bg-slate-900 border border-orange-500/30 rounded-lg p-3 animate-in fade-in duration-200">
            {/* Animated Progress Bar */}
            <div className="h-2 bg-slate-800 rounded-full overflow-hidden mb-2">
              <div
                className="h-full bg-gradient-to-r from-orange-500 via-orange-400 to-orange-500 rounded-full animate-pulse"
                style={{
                  width: status.includes("Critiquing")
                    ? `${Math.min(
                        100,
                        (parseInt(status.match(/\d+/)?.[0] || 0) /
                          parseInt(status.match(/of (\d+)/)?.[1] || 1)) *
                          100
                      )}%`
                    : "100%",
                  animation: status.includes("Critiquing")
                    ? "none"
                    : "shimmer 2s infinite",
                }}
              />
            </div>
            {/* Status Text */}
            <div className="flex items-center gap-2">
              <Icon
                name="loader"
                size={14}
                className="animate-spin text-orange-400"
              />
              <span className="text-xs text-orange-300 font-medium truncate">
                {status || "Generating questions..."}
              </span>
            </div>
          </div>
        )}

        <button
          onClick={handleGenerate}
          data-tour="generate-button"
          disabled={
            isGenerating ||
            isTargetMet ||
            maxBatchSize === 0 ||
            !isApiReady ||
            isRateLimited
          }
          className={`w-full py-4 px-4 rounded-lg font-bold text-white flex items-center justify-center gap-2 transition-all shadow-lg ${
            isGenerating ||
            isTargetMet ||
            maxBatchSize === 0 ||
            !isApiReady ||
            isRateLimited
              ? "bg-slate-700 cursor-not-allowed"
              : "bg-orange-600 hover:bg-orange-700 active:scale-[0.98]"
          }`}
          title={
            !isApiReady
              ? "ΓÜá∩╕Å API Key Required - Configure in Settings"
              : isTargetMet
              ? "Γ£ô Quota Met for this Category"
              : maxBatchSize === 0
              ? "Γ£ô All Categories Complete"
              : "Generate new questions"
          }
        >
          {isGenerating ? (
            <>
              <Icon name="loader" size={16} className="animate-spin" />{" "}
              GENERATING...
            </>
          ) : !isApiReady ? (
            <>
              <Icon name="alert-circle" size={16} /> API KEY REQUIRED
            </>
          ) : isTargetMet ? (
            <>
              <Icon name="check-circle" size={16} /> QUOTA MET
            </>
          ) : (
            <>
              <Icon name="book-open" size={16} /> GENERATE QUESTIONS
            </>
          )}
        </button>

        <button
          onClick={handleBulkTranslateMissing}
          disabled={
            isProcessing ||
            isGenerating ||
            Array.from(allQuestionsMap.keys()).length === 0 ||
            !isApiReady
          }
          className={`w-full py-2 px-4 rounded-lg font-bold text-xs flex items-center justify-center gap-2 transition-all border ${
            isProcessing ||
            isGenerating ||
            Array.from(allQuestionsMap.keys()).length === 0 ||
            !isApiReady
              ? "bg-slate-800 text-slate-600 cursor-not-allowed"
              : "bg-indigo-950/50 text-indigo-400 hover:bg-indigo-900/50 border-indigo-700"
          }`}
          title="Translate accepted English questions to Chinese, Japanese, and Korean"
        >
          <Icon name="languages" size={14} /> BULK TRANSLATE (CN/JP/KR)
        </button>
      </div>

      {/* Shimmer animation for progress bar */}
      <style>{`
                @keyframes shimmer {
                    0% { transform: translateX(-100%); }
                    100% { transform: translateX(100%); }
                }
            `}</style>
    </div>
  );
};

export default ActionFooter;

import { describe, it, expect } from "vitest";
import { renderHook, act } from "@testing-library/react";
import { useToast } from "../useToast";

describe("useToast", () => {
  describe("addToast", () => {
    it("should add a new toast", () => {
      const { result } = renderHook(() => useToast());

      act(() => {
        result.current.addToast("Test message");
      });

      expect(result.current.toasts).toHaveLength(1);
      expect(result.current.toasts[0].message).toBe("Test message");
    });

    it("should not add duplicate messages", () => {
      const { result } = renderHook(() => useToast());

      act(() => {
        result.current.addToast("Same message");
        result.current.addToast("Same message");
      });

      expect(result.current.toasts).toHaveLength(1);
    });

    it("should limit toasts to 3 maximum", () => {
      const { result } = renderHook(() => useToast());

      act(() => {
        result.current.addToast("Message 1");
        result.current.addToast("Message 2");
        result.current.addToast("Message 3");
        result.current.addToast("Message 4");
      });

      expect(result.current.toasts).toHaveLength(3);
    });

    it("should replace matching pattern messages instead of stacking", () => {
      const { result } = renderHook(() => useToast());

      act(() => {
        result.current.addToast("Score: 50/100");
      });

      const firstToastId = result.current.toasts[0].id;

      act(() => {
        result.current.addToast("Score: 75/100");
      });

      expect(result.current.toasts).toHaveLength(1);
      expect(result.current.toasts[0].message).toBe("Score: 75/100");
      expect(result.current.toasts[0].id).toBe(firstToastId); // Same toast, updated
    });

    it("should update existing toast with custom id", () => {
      const { result } = renderHook(() => useToast());

      act(() => {
        result.current.addToast("Initial", { id: "custom-id" });
      });

      act(() => {
        result.current.addToast("Updated", { id: "custom-id" });
      });

      expect(result.current.toasts).toHaveLength(1);
      expect(result.current.toasts[0].message).toBe("Updated");
    });
  });

  describe("removeToast", () => {
    it("should remove toast by id", () => {
      const { result } = renderHook(() => useToast());

      act(() => {
        result.current.addToast("Test", { id: "remove-me" });
      });

      expect(result.current.toasts).toHaveLength(1);

      act(() => {
        result.current.removeToast("remove-me");
      });

      expect(result.current.toasts).toHaveLength(0);
    });
  });

  describe("updateProgress", () => {
    it("should update progress on existing toast", () => {
      const { result } = renderHook(() => useToast());

      act(() => {
