import { useCallback } from "react";
import {
  generateCritiqueSecure as generateCritique,
  generateTagsSecure,
} from "../../services/geminiSecure";
import { QUALITY_THRESHOLDS, TOAST_DURATION } from "../../utils/constants";

/**
 * Hook for handling question critique and feedback loop logic.
 * Extracted from useGeneration to reduce complexity.
 */
export const useQuestionCritique = ({
  effectiveApiKey,
  isApiReady,
  showMessage,
  setStatus,
  setIsProcessing,
  updateQuestionInState,
  updateAllVariantsInState,
}) => {
  /**
   * Generates a critique and suggested rewrite for a question.
   */
  const handleCritique = useCallback(
    async (q) => {
      if (!isApiReady) {
        showMessage(
          "API key is required for critique. Please enter it in the settings panel.",
          TOAST_DURATION.LONG
        );
        return;
      }

      setIsProcessing(true);
      setStatus("Critiquing...");

      try {
        const { score, text, rewrite, improvedScore, changes } =
          await generateCritique(effectiveApiKey, q);

        // Generate tags if question has fewer than 3
        let suggestedTags = Array.isArray(q.tags) ? q.tags : [];
        if (suggestedTags.length < 3) {
          try {
            const questionForTags = rewrite
              ? {
                  question: rewrite.question || q.question,
                  optionA: rewrite.optionA || q.options?.A,
                  optionB: rewrite.optionB || q.options?.B,
                  optionC: rewrite.optionC || q.options?.C,
                  optionD: rewrite.optionD || q.options?.D,
                }
              : {
                  question: q.question,
                  optionA: q.options?.A,
                  optionB: q.options?.B,
                  optionC: q.options?.C,
                  optionD: q.options?.D,
                };

            const newTags = await generateTagsSecure(
              effectiveApiKey,
              questionForTags
            );
            if (newTags && newTags.length > 0) {
              suggestedTags = [
                ...new Set([
                  ...suggestedTags,
                  ...newTags.map((t) => t.replace(/^#/, "")),
                ]),
              ].slice(0, 5);
            }
          } catch (error) {
            console.error("Tag generation failed during critique:", error);
          }
        }

        const updatedRewrite = rewrite
          ? {
              question: rewrite.question || q.question,
              options: {
                A: rewrite.optionA || q.options?.A || "",
                B: rewrite.optionB || q.options?.B || "",
                C: rewrite.optionC || q.options?.C || "",
                D: rewrite.optionD || q.options?.D || "",
              },
              correct: rewrite.correctLetter || q.correct || "A",
              improvements: Array.isArray(changes)
                ? changes
                : changes
                ? [changes]
                : [],
              critiqueScore: improvedScore,
              critiqueText: text,
              tags: suggestedTags,
              changesExplanation:
                rewrite.explanation ||
                "AI-suggested improvements to enhance question quality",
            }
          : null;

        const previousAttempts = q.critiqueAttempts || 0;
        const newAttemptCount = previousAttempts + 1;
        const PASSING_SCORE = QUALITY_THRESHOLDS.PASS;
        const MAX_ATTEMPTS = 3;

        const critiqueUpdate = (item) => ({
          ...item,
          critique: text,
          critiqueScore: score,
          improvedScore: improvedScore,
          suggestedRewrite: updatedRewrite,
          rewriteChanges: changes,
          critiqueAttempts: newAttemptCount,
          ...(score < PASSING_SCORE && newAttemptCount >= MAX_ATTEMPTS
            ? {
                status: "rejected",
                rejectionReason: "low_score_after_retries",
                rejectedAt: new Date().toISOString(),
              }
            : {}),
        });

        if (q.uniqueId) {
          updateAllVariantsInState(q.uniqueId, critiqueUpdate);
          updateQuestionInState(q.id, critiqueUpdate);
        } else {
          updateQuestionInState(q.id, critiqueUpdate);
        }

        if (score < PASSING_SCORE && newAttemptCount >= MAX_ATTEMPTS) {
          showMessage(
            `\u26D4 Auto-rejected: Score ${score}/100 after ${newAttemptCount} attempts. Quality too low.`,
            TOAST_DURATION.EXTENDED
          );
        } else {
          showMessage(
            `Critique Ready! Score: ${score}/100`,
            TOAST_DURATION.MEDIUM
          );
        }
      } catch (e) {
        console.error("Critique failed:", e);
        setStatus("Fail");
        showMessage(`Critique Failed: ${e.message}`, TOAST_DURATION.LONG);
      } finally {
        setIsProcessing(false);
      }
    },
    [
      isApiReady,
      showMessage,
      effectiveApiKey,
      updateQuestionInState,
      updateAllVariantsInState,
      setStatus,
      setIsProcessing,
    ]
  );

  /**
   * Applies the suggested rewrite to the question.
   */
  const handleApplyRewrite = useCallback(
    (q) => {
      if (!q.suggestedRewrite) return;

      const updatedQ = {
        ...q,
        question: q.suggestedRewrite.question,
        options: q.suggestedRewrite.options,
        correct: q.suggestedRewrite.correct,
        suggestedRewrite: null,
        rewriteChanges: null,
        critique: null,
        critiqueScore: null,
        humanVerified: false,
        status: "pending",
        rejectionReason: null,
      };

      updateQuestionInState(q.id, () => updatedQ);
      showMessage("Γ£ô Applied! Re-critiquing...", TOAST_DURATION.SHORT);

      // Re-trigger critique after a short delay
      setTimeout(() => {
        handleCritique({ ...updatedQ, id: q.id });
      }, 300);
    },
    [updateQuestionInState, showMessage, handleCritique]
  );

  return {
    handleCritique,
    handleApplyRewrite,
  };
};

/**
 * Intelligently converts a Multiple Choice question to True/False format.
 * Creates a statement from the question + correct answer, randomly makes it TRUE or FALSE.
 * 
 * @param {Object} mcQuestion - The multiple choice question object
 * @param {string} mcQuestion.question - The question text
 * @param {Object} mcQuestion.options - The answer options (A, B, C, D)
 * @param {string} mcQuestion.correct - The correct answer letter
 * @param {string} difficulty - The difficulty level to assign
 * @returns {Object} The converted True/False question
 */
export const convertMCtoTF = (mcQuestion, difficulty) => {
    const correctAnswerText = mcQuestion.options[mcQuestion.correct];
    const wrongAnswers = Object.entries(mcQuestion.options)
        .filter(([key, val]) => key !== mcQuestion.correct && val && val.trim())
        .map(([, val]) => val);

    // Check if the original question is already effectively True/False
    const lowerCorrect = correctAnswerText.trim().toLowerCase().replace(/[.,!]$/, '');
    const isBooleanAnswer = ['true', 'false', 'yes', 'no'].includes(lowerCorrect);

    let newStatement = mcQuestion.question.trim().replace(/\?$/, '');
    let makeItTrue = true; // Default
    let targetAnswer = correctAnswerText;

    if (isBooleanAnswer) {
        // PRESERVE MODE: If original answer is True/False, we keep the statement as is.
        // We cannot easily flip the truthiness of a statement without complex NLP (e.g. adding "not").
        // So we force the new question to match the original truthiness.

        // If original correct was "TRUE" or "YES" -> New Correct is A (TRUE)
        if (['true', 'yes'].includes(lowerCorrect)) {
            makeItTrue = true;
        }
        // If original correct was "FALSE" or "NO" -> New Correct is B (FALSE)
        else {
            makeItTrue = false;
        }

        // Statement is just the original question text (which is likely a statement)
        // newStatement remains the same
    } else {
        // STANDARD MODE: Randomly decide if this will be a TRUE or FALSE question (50/50)
        makeItTrue = Math.random() > 0.5;
        targetAnswer = makeItTrue ? correctAnswerText : wrongAnswers[Math.floor(Math.random() * wrongAnswers.length)] || 'incorrect';

        // 1. Handle "Can you..." -> "You can [stem] [answer]"
        if (/^Can you/i.test(newStatement)) {
            const stem = newStatement.replace(/^Can you\s+/i, '');
            newStatement = `You can ${stem} ${targetAnswer}`;
        }
        // 2. Handle "Is..." -> "[Subject] is [Answer]"
        else if (/^Is\s+/i.test(newStatement)) {
            const stem = newStatement.replace(/^Is\s+/i, '');
            newStatement = `${stem} is ${targetAnswer}`;
        }
        // 3. Handle "What/Which..." -> "[Stem] is [Answer]"
        else {
            // Check for WH- words
            const isWhQuestion = /^(What|Which|How|Where|When|Why)\s+/i.test(newStatement);

            if (isWhQuestion) {
                const stem = newStatement
                    .replace(/^(What|Which|How|Where|When|Why)\s+(is|are|does|do|can|should|would)\s+/i, '')
                    .trim();
                newStatement = `${stem} is ${targetAnswer}`;
            } else {
                // Fallback for other structures: append answer
                newStatement = `${newStatement} is ${targetAnswer}`;
            }
        }
    }

    // Cleanup: Remove double spaces, capitalize, add period
    newStatement = newStatement.replace(/\s+/g, ' ').trim();
    newStatement = newStatement.charAt(0).toUpperCase() + newStatement.slice(1);
    if (!newStatement.endsWith('.')) newStatement += '.';

    return {
        ...mcQuestion,
        type: 'True/False',
        difficulty: difficulty,
        question: newStatement,
        options: { A: 'TRUE', B: 'FALSE', C: '', D: '' },
        correct: makeItTrue ? 'A' : 'B',
        originalMC: mcQuestion.question // Keep original for reference
    };
};

import { useCallback } from "react";
import { getCSVContent, segmentQuestions } from "../utils/exportUtils";
import {
  saveQuestionsToSheets,
  fetchQuestionsFromSheets,
} from "../services/googleSheets";
import {
  saveQuestionToFirestore,
  getAllQuestionsFromFirestore,
} from "../services/firebase";
import { downloadFile } from "../utils/questionHelpers";
import { formatDate } from "../utils/dateHelpers";

export const useExport = (
  config,
  questions,
  historicalQuestions,
  uniqueFilteredQuestions,
  allQuestionsMap,
  showHistory,
  showMessage,
  setStatus,
  setIsProcessing,
  setDatabaseQuestions,
  setAppMode,
  setShowExportMenu,
  setShowBulkExportModal,
  setHistoricalQuestions
) => {
  const handleExportByGroup = useCallback(() => {
    const sourceList = showHistory
      ? [...questions, ...historicalQuestions]
      : questions;
    const valid = sourceList.filter((q) => q.status !== "rejected");

    if (valid.length === 0) {
      setStatus("No accepted questions to export.");
      setTimeout(() => setStatus(""), 3000);
      return;
    }

    const groupedData = segmentQuestions(valid);

    let filesGenerated = 0;
    const exportDate = new Date();
    const datePart = formatDate(exportDate).replace(/-/g, "");

    Object.keys(groupedData).forEach((groupKey) => {
      const groupQuestions = groupedData[groupKey];
      const csvContent = getCSVContent(
        groupQuestions,
        config.creatorName,
        config.reviewerName
      );

      const fileNameParts = groupKey.replace(/ & /g, "_").replace(/ /g, "_");
      const filename = `${fileNameParts}_${datePart}.csv`;

      downloadFile(csvContent, filename);
      filesGenerated++;
    });

    setStatus(`Exported ${filesGenerated} segmented files.`);
    setTimeout(() => setStatus(""), 5000);
    if (setShowExportMenu) setShowExportMenu(false);
  }, [
    showHistory,
    questions,
    historicalQuestions,
    setStatus,
    config.creatorName,
    config.reviewerName,
    setShowExportMenu,
  ]);

  const handleExportCurrentTarget = useCallback(() => {
    const sourceList = showHistory
      ? [...questions, ...historicalQuestions]
      : questions;

    const targetString = config.difficulty;
    const [targetDiff, targetTypeAbbrev] = targetString.split(" ");
    const targetType =
      targetTypeAbbrev === "MC" ? "Multiple Choice" : "True/False";

    const valid = sourceList.filter(
      (q) =>
        q.status !== "rejected" &&
        (q.language || "English") === config.language &&
        q.discipline === config.discipline &&
        q.difficulty === targetDiff &&
        q.type === targetType
    );

    if (valid.length === 0) {
      setStatus(
        `No accepted questions found for target: ${config.language} - ${targetString}`
      );
      setTimeout(() => setStatus(""), 3000);
      return;
    }

    const typePart = targetString.replace(/\s/g, "_");
    const disciplinePart = config.discipline.replace(/\s/g, "_");
    const datePart = new Date().toISOString().split("T")[0].replace(/-/g, "");
    const langPart = (config.language || "English").replace(/ /g, "_");

    const csvContent = getCSVContent(
      valid,
      config.creatorName,
      config.reviewerName
    );
    const filename = `${langPart}_${disciplinePart}_${typePart}_${datePart}.csv`;
    downloadFile(csvContent, filename);
    setStatus(`Exported ${valid.length} questions for target ${targetString}`);
    setTimeout(() => setStatus(""), 5000);
    if (setShowExportMenu) setShowExportMenu(false);
  }, [
    showHistory,
    questions,
    historicalQuestions,
    config.difficulty,
    config.language,
    config.discipline,
    setStatus,
    config.creatorName,
    config.reviewerName,
    setShowExportMenu,
  ]);

  const handleExportToSheets = useCallback(async () => {
    if (!config.sheetUrl) {
      showMessage("Please enter a Google Apps Script URL in settings.", 5000);
      return;
    }

    const sourceList = showHistory
      ? [...questions, ...historicalQuestions]
      : questions;
    const validQuestions = sourceList.filter((q) => q.status !== "rejected");

    if (validQuestions.length === 0) {
      showMessage("No accepted questions to export.", 3000);
      return;
    }

    setIsProcessing(true);
    setStatus("Sending data to Google Sheets...");
    if (setShowExportMenu) setShowExportMenu(false);

    try {
      // Dual Write: Save to Sheets AND Firestore
      await Promise.all([
        saveQuestionsToSheets(config.sheetUrl, validQuestions),
        Promise.all(validQuestions.map((q) => saveQuestionToFirestore(q))),
      ]);

      showMessage(
        `Export launched! Data synced to Sheets and Firestore.`,
        7000
      );
    } catch (e) {
      console.error("Error pushing to Sheets endpoint:", e);
      showMessage(
        `Error connecting to endpoint. Check URL/Console: ${e.message}`,
        10000
      );
    } finally {
      setIsProcessing(false);
    }
  }, [
    config.sheetUrl,
    showMessage,
    showHistory,
    questions,
    historicalQuestions,
    setIsProcessing,
    setStatus,
    setShowExportMenu,
  ]);

  const handleLoadFromSheets = useCallback(async () => {
    if (!config.sheetUrl) {
      showMessage("Please enter a Google Apps Script URL first.", 3000);
      return;
    }

    setIsProcessing(true);
    setStatus("Loading from Google Sheets...");
    if (setShowExportMenu) setShowExportMenu(false);

    try {
      const data = await fetchQuestionsFromSheets(config.sheetUrl);
      const loadedQuestions = data.map((q, index) => ({
        id: Date.now() + index + Math.random(),
        uniqueId: q["Unique ID"] || q.uniqueId || crypto.randomUUID(),
        discipline: q.Discipline || q.discipline || "Imported",
        difficulty: q.Difficulty || q.difficulty || "Easy",
        type: q["Question Type"] || q.Type || q.type || "Multiple Choice",
        question: q.Question || q.question || "",
        options: {
          A: q["Option A"] || q.OptionA || "",
          B: q["Option B"] || q.OptionB || "",
          C: q["Option C"] || q.OptionC || "",
          D: q["Option D"] || q.OptionD || "",
        },
        correct: q.Answer || q.correct || "",
        explanation: q.Explanation || q.explanation || "",
        language: q.Language || q.language || "English",
        sourceUrl: q.SourceFile || q.sourceUrl || "",
        sourceExcerpt: q.sourceExcerpt || "",
        creatorName: q.creator || q.creatorName || "",
        reviewerName: q.reviewer || q.reviewerName || "",
        status: "accepted",
      }));

      setDatabaseQuestions(loadedQuestions);
      if (setHistoricalQuestions) setHistoricalQuestions(loadedQuestions);

      // Only switch to database view if NOT in review mode
      // Actually, user might want to see it in DB view first.
      // Let's keep behavior but ensure data is available for review.
      setAppMode("database");
      showMessage(
        `Loaded ${loadedQuestions.length} questions from Database View!`,
        3000
      );
    } catch (e) {
      console.error("Load Error:", e);
      showMessage(
        `Load Failed: ${e.message}. (Ensure Script Access is set to 'Anyone')`,
        7000
      );
    } finally {
      setIsProcessing(false);
      setStatus("");
    }
  }, [
    config.sheetUrl,
    showMessage,
    setIsProcessing,
    setStatus,
    setShowExportMenu,
    setDatabaseQuestions,
    setHistoricalQuestions,
    setAppMode,
  ]);

  const handleLoadFromFirestore = useCallback(
    async (silent = false) => {
      setIsProcessing(true);
      setStatus(silent ? "" : "Loading from Firestore...");
      if (setShowExportMenu) setShowExportMenu(false);

      try {
        // Use getAllQuestionsFromFirestore for shared database view (all authenticated users can see all questions)
        const data = await getAllQuestionsFromFirestore();

        // PERFORMANCE: Load once to prevent re-render loops
        const loadedQuestions = data.map((q, index) => ({
          ...q,
          id: q.id || Date.now() + index + Math.random(), // Ensure React key
          status: q.status || "pending", // CRITICAL: Preserve actual status
        }));

        setDatabaseQuestions(loadedQuestions);
        if (setHistoricalQuestions) setHistoricalQuestions(loadedQuestions);

        if (!silent) {
          showMessage(
            `Loaded ${loadedQuestions.length} questions from Firestore!`,
            3000
          );
        }
      } catch (e) {
        console.error("Firestore Load Error:", e);
        if (!silent) {
          showMessage(`Firestore Load Failed: ${e.message}`, 7000);
        }
      } finally {
        setIsProcessing(false);
        setStatus("");
      }
    },
    [
      setIsProcessing,
      setStatus,
      setShowExportMenu,
      setDatabaseQuestions,
      setHistoricalQuestions,
      showMessage,
    ]
  );

  const handleBulkExport = useCallback(
    async (exportOptions) => {
      const { format, includeRejected, languages, scope, segmentFiles, limit } =
        exportOptions;

      let sourceQuestions = [];
      if (scope === "filtered") {
        const visibleIds = new Set(
          uniqueFilteredQuestions.map((q) => q.uniqueId)
        );
        sourceQuestions = Array.from(allQuestionsMap.values()).flatMap(
          (variants) => variants.filter((v) => visibleIds.has(v.uniqueId))
        );
      } else {
        sourceQuestions = Array.from(allQuestionsMap.values()).flat();
      }

      let questionsToExport = sourceQuestions.filter((q) => {
        const langMatch = languages.includes(q.language || "English");
        const statusMatch = includeRejected || q.status !== "rejected";
        return langMatch && statusMatch;
      });

      if (limit && limit > 0) {
        questionsToExport = questionsToExport.slice(0, limit);
      }

      if (questionsToExport.length === 0) {
        showMessage("No questions to export with selected options.", 3000);
        return;
      }

      if (format === "sheets") {
        if (!config.sheetUrl) {
          showMessage(
            "Please enter a Google Apps Script URL in settings.",
            5000
          );
          return;
        }
        setIsProcessing(true);
        setStatus("Sending data to Google Sheets...");
        try {
          await saveQuestionsToSheets(config.sheetUrl, questionsToExport);
          showMessage(`Export launched! Check new tab for status.`, 5000);
        } catch (e) {
          console.error(e);
          showMessage(`Error: ${e.message}`, 5000);
        } finally {
          setIsProcessing(false);
        }
        return;
      }

      if (segmentFiles && format === "csv") {
        const groupedData = questionsToExport.reduce((acc, q) => {
          const typeAbbrev = q.type === "True/False" ? "T/F" : "MC";
          const key = `${q.language || "English"}_${q.discipline}_${
            q.difficulty
          }_${typeAbbrev}`;
          if (!acc[key]) acc[key] = [];
          acc[key].push(q);
          return acc;
        }, {});

        let filesGenerated = 0;
        const datePart = formatDate(new Date()).replace(/-/g, "");

        Object.keys(groupedData).forEach((groupKey) => {
          const groupQuestions = groupedData[groupKey];
          const csvContent = getCSVContent(
            groupQuestions,
            config.creatorName,
            config.reviewerName
          );
          const fileNameParts = groupKey
            .replace(/ & /g, "_")
            .replace(/ /g, "_");
          const filename = `${fileNameParts}_${datePart}.csv`;
          downloadFile(csvContent, filename);
          filesGenerated++;
        });
        showMessage(`Exported ${filesGenerated} segmented files.`, 4000);
        return;
      }

      if (format === "csv") {
        const csvContent = getCSVContent(
          questionsToExport,
          config.creatorName,
          config.reviewerName
        );
        downloadFile(csvContent, `bulk_export_${Date.now()}.csv`, "text/csv");
      } else if (format === "json") {
        downloadFile(
          JSON.stringify(questionsToExport, null, 2),
          `bulk_export_${Date.now()}.json`,
          "application/json"
        );
      } else if (format === "markdown") {
        const md = questionsToExport
          .map((q) => {
            return `## ${q.question}\n\n**Difficulty:** ${
              q.difficulty
            } | **Type:** ${q.type} | **Language:** ${
              q.language
            }\n\n**Options:**\n- A: ${q.options?.A}\n- B: ${q.options?.B}\n${
              q.options?.C ? `- C: ${q.options.C}\n` : ""
            }${q.options?.D ? `- D: ${q.options.D}\n` : ""}\n**Correct:** ${
              q.correct
            }\n\n---\n`;
          })
          .join("\n");
        downloadFile(md, `bulk_export_${Date.now()}.md`, "text/markdown");
      }

      showMessage(
        `Exported ${
          questionsToExport.length
        } questions as ${format.toUpperCase()}.`,
        4000
      );
    },
    [
      uniqueFilteredQuestions,
      allQuestionsMap,
      showMessage,
      config.sheetUrl,
      setIsProcessing,
      setStatus,
      config.creatorName,
      config.reviewerName,
    ]
  );

  return {
    handleExportByGroup,
    handleExportCurrentTarget,
    handleExportToSheets,
    handleLoadFromSheets,
    handleLoadFromFirestore,
    handleBulkExport,
  };
};

import { useState, useEffect, useMemo, useCallback } from "react";
import { getSecureItem, setSecureItem } from "../utils/secureStorage";
import { filterDuplicateQuestions } from "../utils/questionHelpers";
import {
  CATEGORY_KEYS,
  TARGET_PER_CATEGORY,
  TARGET_TOTAL,
} from "../utils/constants";
import {
  saveQuestionToFirestore,
  getQuestionsPaginated,
  deleteQuestionFromFirestore,
} from "../services/firebase";
import { logQuestion } from "../utils/analyticsStore";
import { completeReviewTracking } from "../utils/normalizeQuestion";
import { getAgents } from "../agents";

export const useQuestionManager = (config, showMessage) => {
  // Current session questions
  const [questions, setQuestions] = useState(() => {
    const saved = getSecureItem("ue5_gen_questions");
    return saved || [];
  });

  // Historical questions
  const [historicalQuestions, setHistoricalQuestions] = useState([]);

  // Database view questions
  const [databaseQuestions, setDatabaseQuestions] = useState([]);

  // PERFORMANCE: Pagination state
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [lastDoc, setLastDoc] = useState(null);

  // Version tracking for concurrent editing (maps question ID -> version)
  const [questionVersions, setQuestionVersions] = useState(new Map());

  // Conflict resolution state
  const [conflictData, setConflictData] = useState(null);
  const [showConflictModal, setShowConflictModal] = useState(false);

  // Delete confirmation state
  const [deleteConfirmId, setDeleteConfirmId] = useState(null);
  const [showClearModal, setShowClearModal] = useState(false);

  // Get concurrent editing agents
  const agents = getAgents();

  // Persist session questions
  useEffect(() => setSecureItem("ue5_gen_questions", questions), [questions]);

  // Sync questions across browser tabs via storage event
  useEffect(() => {
    const handleStorageChange = (e) => {
      if (e.key === "ue5_gen_questions" && e.newValue) {
        try {
          const newQuestions = JSON.parse(e.newValue);
          console.log(
            `≡ƒöä Syncing ${newQuestions.length} questions from another tab...`
          );
          setQuestions(newQuestions);
        } catch (err) {
          console.error("Failed to sync questions from storage:", err);
        }
      }
    };

    window.addEventListener("storage", handleStorageChange);
    return () => window.removeEventListener("storage", handleStorageChange);
  }, []);

  // Backfill creatorName on questions missing it
  useEffect(() => {
    if (!config.creatorName) return; // No name to backfill with

    const questionsNeedingBackfill = questions.filter(
      (q) =>
        !q.creatorName || q.creatorName === "N/A" || q.creatorName === "Unknown"
    );
    if (questionsNeedingBackfill.length > 0) {
      console.log(
        `≡ƒô¥ Backfilling creatorName on ${questionsNeedingBackfill.length} questions...`
      );
      setQuestions((prev) =>
        prev.map((q) => {
          if (
            !q.creatorName ||
            q.creatorName === "N/A" ||
            q.creatorName === "Unknown"
          ) {
            return { ...q, creatorName: config.creatorName };
          }
          return q;
        })
      );
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [config.creatorName]); // Only run when creatorName changes

  // Central question storage map - memoized for performance and stability
  const allQuestionsMap = useMemo(() => {
    const combined = [
      ...questions,
      ...historicalQuestions,
      ...databaseQuestions,
    ];

    const newMap = new Map();

    combined.forEach((q) => {
      const id = q.uniqueId || q.id;
      if (!id) return;
      if (!newMap.has(id)) newMap.set(id, []);

      const variants = newMap.get(id);
      const lang = q.language || "English";

      // Dedupe by language within each uniqueId bucket to prevent double-counting
      if (!variants.some((v) => (v.language || "English") === lang)) {
        variants.push(q);
      }
    });

    return newMap;
  }, [questions, historicalQuestions, databaseQuestions]);

  // Translation Map - derived from the stable allQuestionsMap
  const translationMap = useMemo(() => {
    const map = new Map();
    Array.from(allQuestionsMap.keys()).forEach((uniqueId) => {
      const variants = allQuestionsMap.get(uniqueId);
      const langSet = new Set(variants.map((v) => v.language || "English"));
      map.set(uniqueId, langSet);
    });
    return map;
  }, [allQuestionsMap]);

  // Helper to add questions with automatic cloud backup
  const addQuestionsToState = useCallback(
    async (newItems, isHistory = false, insertAfterId = null) => {
      // Auto-save to Firestore for crash protection
      if (newItems && newItems.length > 0) {
