/**
 * Classifies a question into one of the 7 disciplines.
 * @param {string} apiKey
 * @param {string} questionText
 * @returns {Promise<string>} The discipline name
 */
export const classifyQuestionDiscipline = async (apiKey, questionText) => {
  const systemPrompt = `You are an expert UE5 classifier.
  Classify the following question into exactly ONE of these disciplines:
  - Worldbuilding
  - Game Dev
  - Look Dev
  - Tech Art
  - VFX
  - Animation
  - Programming

  Return ONLY the discipline name.`;

  const userPrompt = `Classify this question: "${questionText}"`;

  const baseUrl =
    "https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent";
  const url = apiKey ? `${baseUrl}?key=${apiKey}` : baseUrl;

  const data = await fetchWithRetry(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      contents: [{ parts: [{ text: userPrompt }] }],
      systemInstruction: { parts: [{ text: systemPrompt }] },
      generationConfig: { temperature: 0.1, maxOutputTokens: 20 },
    }),
  });

  return (data.candidates?.[0]?.content?.parts?.[0]?.text || "").trim();
};

/**
 * Generates 3-5 relevant tags for a question.
 * @param {string} apiKey
 * @param {string} questionText
 * @returns {Promise<string[]>} Array of tags
 */
export const generateTagsForQuestion = async (apiKey, questionText) => {
  const systemPrompt = `You are an expert UE5 tagger.
    Generate 3-5 relevant technical tags for the provided question.
    - Tags should be specific (e.g., "Blueprints", "Lumen", "Niagara").
    - Return ONLY a valid JSON array of strings.
    - Example: ["Blueprints", "Actors", "Level Design"]`;

  const userPrompt = `Tags for: "${questionText}"`;

  const baseUrl =
    "https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent";
  const url = apiKey ? `${baseUrl}?key=${apiKey}` : baseUrl;

  const data = await fetchWithRetry(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      contents: [{ parts: [{ text: userPrompt }] }],
      systemInstruction: { parts: [{ text: systemPrompt }] },
      generationConfig: {
        temperature: 0.3,
        maxOutputTokens: 100,
        responseMimeType: "application/json",
      },
    }),
  });

  const text = data.candidates?.[0]?.content?.parts?.[0]?.text || "[]";
  try {
    return JSON.parse(text);
  } catch (e) {
    console.error("Failed to parse tags:", text, e);
    return [];
  }
};

/**
 * Lists available models for the given API key.
 * @param {string} apiKey
 * @returns {Promise<string[]>} List of model names
 */
export const listModels = async (apiKey) => {
  const baseUrl = "https://generativelanguage.googleapis.com/v1beta/models";
  const url = apiKey ? `${baseUrl}?key=${apiKey}` : baseUrl;
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`List Models Failed: ${response.status}`);
    const data = await response.json();
    return data.models?.map((m) => m.name.replace("models/", "")) || [];
  } catch (error) {
    console.error("Failed to list models:", error);
    return [];
  }
};

const stripHtmlTags = (str) => {
    if (!str) return '';
    return str.replace(/<[^>]*>/g, '');
};

export const fetchQuestionsFromSheets = (sheetUrl) => {
    return new Promise((resolve, reject) => {
        // Create a unique callback name
        const callbackName = 'jsonp_callback_' + Math.round(100000 * Math.random());

        // Define the callback function globally
        window[callbackName] = (data) => {
            delete window[callbackName];
            document.body.removeChild(script);
            if (data.status === 'Success' && Array.isArray(data.data)) {
                resolve(data.data);
            } else {
                reject(new Error(data.message || "Invalid data format received"));
            }
        };

        // Create the script element
        const script = document.createElement('script');
        // Append callback parameter to URL
        const separator = sheetUrl.includes('?') ? '&' : '?';
        script.src = `${sheetUrl}${separator}callback=${callbackName}&action=read`;
        script.onerror = () => {
            delete window[callbackName];
            document.body.removeChild(script);
            reject(new Error("Connection failed. 1. Ensure you added the 'doGet' function. 2. Redeploy as 'New Version'. 3. Set Access to 'Anyone'."));
        };

        // Append to body to trigger request
        document.body.appendChild(script);
    });
};

export const saveQuestionsToSheets = async (sheetUrl, questions) => {
    // Transform into JSON array matching CSV structure (without headers)
    const payloadData = questions.map((row, i) => {
        const cleanedSourceUrl = row.sourceUrl && !row.sourceUrl.includes("grounding-api") ? row.sourceUrl : "";
        const o = row.options || {};
        // Return data fields matching the User's Google Apps Script expected keys
        return {
            "ID": (i + 1).toString(), // Changed from "id" to "ID"
            "uniqueId": row.uniqueId, // This field is not used in the new GAS, but kept for consistency
            "Status": row.status || 'accepted', // Added Status
            "Discipline": row.discipline, // Changed from "discipline" to "Discipline"
            "Type": row.type, // Changed from "type" to "Type"
            "Difficulty": row.difficulty, // Changed from "difficulty" to "Difficulty"
            "Question": stripHtmlTags(row.question), // Changed from "question" to "Question"
            "OptionA": stripHtmlTags(o.A), // Changed from "optionA" to "OptionA"
            "OptionB": stripHtmlTags(o.B), // Changed from "optionB" to "OptionB"
            "OptionC": stripHtmlTags(o.C), // Changed from "optionC" to "OptionC"
            "OptionD": stripHtmlTags(o.D || ""), // Changed from "optionD" to "OptionD"
            "Answer": row.correct, // Changed from "correctAnswer" to "Answer"
            "Explanation": stripHtmlTags(row.explanation || ""), // Added Explanation
            "Language": row.language || "English", // Changed from "language" to "Language"
            "SourceFile": cleanedSourceUrl, // Changed from "sourceUrl" to "SourceFile"
            "sourceExcerpt": stripHtmlTags(row.sourceExcerpt), // This field is not used in the new GAS, but kept for consistency
            "creator": row.creatorName, // This field is not used in the new GAS, but kept for consistency
            "reviewer": row.reviewerName, // This field is not used in the new GAS, but kept for consistency
            "QualityScore": row.critiqueScore || row.initialQuality || "",
            "AICritique": stripHtmlTags(row.critique || ""),
            "TokenCost": row.tokenCost || "", // Added Token Cost
            "RejectionReason": row.rejectionReason || "",
            "HumanVerifiedBy": row.humanVerifiedBy || "",
            "RejectedAt": row.rejectedAt || ""
        };
    });

    // The new GAS expects a 'questions' array inside the 'data' parameter
    const finalPayload = { questions: payloadData };

    // Use a new tab to submit the form. 
    // This ensures that if there is an Auth/Permission error (403), the user SEES it.
    // Hidden iframes swallow auth errors silently.
    const form = document.createElement('form');
    form.method = 'POST';
    form.action = sheetUrl;
    form.target = 'SheetsSaving'; // Open in popup window

    // Open popup window
    window.open('', 'SheetsSaving', 'width=600,height=500');

    const input = document.createElement('input');
    input.type = 'hidden';
    input.name = 'data';
    input.value = JSON.stringify(finalPayload); // Stringify the final payload
    form.appendChild(input);

    document.body.appendChild(form);
    form.submit();

    // Clean up form after submission
    setTimeout(() => {
        document.body.removeChild(form);
    }, 1000);
};

export const clearQuestionsFromSheets = async (sheetUrl) => {
    if (!sheetUrl) {
        alert('Error: No Google Sheet URL configured. Please add your Sheet URL in Settings.');
        return;
    }

    // Open a popup window that can be closed programmatically
    const popup = window.open('', 'SheetsClearing', 'width=600,height=400');
    if (popup) {
        popup.document.write('<html><body style="background:#111827;color:#9ca3af;font-family:sans-serif;display:flex;align-items:center;justify-content:center;height:100vh;margin:0;"><div style="text-align:center;"><h2>Clearing Google Sheets...</h2><p>Please wait...</p></div></body></html>');
    }

    const form = document.createElement('form');
    form.method = 'POST';
    // Append action as URL parameter so Google Apps Script can read it via e.parameter
    const separator = sheetUrl.includes('?') ? '&' : '?';
    form.action = `${sheetUrl}${separator}action=clear`;
    form.target = 'SheetsClearing'; // Target the popup window

    document.body.appendChild(form);
    form.submit();

    setTimeout(() => {
        document.body.removeChild(form);
    }, 1000);
};

import JSZip from "jszip";

/**
 * SCORM 1.2 Exporter Service
 * Converts Firestore questions to SCORM packages
 */

/**
 * Convert a Firestore question to SCORM quiz format
 * @param {Object} question - Firestore question object
 * @returns {Object} SCORM-formatted question
 */
export function convertQuestionToScormFormat(question) {
  const { questionText, type, choices, correctAnswer, guid, difficulty } =
    question;

  // For Multiple Choice: choices is array of strings, correctAnswer is the correct string
  // For True/False: choices is ["True", "False"], correctAnswer is "True" or "False"

  const scormChoices = choices.map((choiceText) => ({
    text: choiceText,
    correct: choiceText === correctAnswer,
  }));

  return {
    id: guid || `q-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
    text: questionText,
    type: type,
    difficulty: difficulty || "Medium",
    choices: scormChoices,
  };
}

/**
 * Generate SCORM package configuration
 * @param {Array} questions - Array of Firestore questions
 * @param {Object} config - Package configuration
 * @returns {Object} Package files ready for zipping
 */
export async function generateScormPackageFiles(questions, config = {}) {
  const {
    title = "UE5 Knowledge Assessment",
    description = "Test your Unreal Engine 5 knowledge",
    passingScore = 80,
    timeLimit = 30, // minutes
  } = config;

  // Convert questions to SCORM format
  const scormQuestions = questions.map(convertQuestionToScormFormat);

  // Load template files from public directory
  const templatePath = "/scorm-template/";

  // Fetch template files
  const [scormJs, indexHtml, styleCSS, gameJs, manifest] = await Promise.all([
    fetch(`${templatePath}scorm.js`).then((r) => r.text()),
    fetch(`${templatePath}index.html`).then((r) => r.text()),
    fetch(`${templatePath}style.css`).then((r) => r.text()),
    fetch(`${templatePath}game.js`).then((r) => r.text()),
    fetch(`${templatePath}imsmanifest.xml`).then((r) => r.text()),
  ]);

  // Replace template variables in manifest
  const processedManifest = manifest
    .replace(/UE5 Scenario Tracker/g, title)
    .replace(
      /com\.example\.ue5scenario\.scorm12/g,
      `com.ue5questiongen.${Date.now()}`
    );

  // Replace template variables in index.html
  const processedIndexHtml = indexHtml.replace(/UE5 Scenario Tracker/g, title);

  // Create questions.js file with our questions
  const questionsJs = `// Generated questions for SCORM package
// Generated: ${new Date().toISOString()}

window.QUIZ_CONFIG = {
  title: "${title}",
  description: "${description}",
  passingScore: ${passingScore},
  timeLimit: ${timeLimit * 60}, // Convert minutes to seconds
  totalQuestions: ${scormQuestions.length}
};

window.QUESTIONS = ${JSON.stringify(scormQuestions, null, 2)};
`;

  return {
    "scorm.js": scormJs,
    "index.html": processedIndexHtml,
    "style.css": styleCSS,
    "game.js": gameJs,
    "questions.js": questionsJs,
    "imsmanifest.xml": processedManifest,
  };
}

/**
 * Generate and download SCORM package as .zip file
 * @param {Array} questions - Array of Firestore questions
 * @param {Object} config - Package configuration
 */
export async function exportToScorm(questions, config = {}) {
  if (!questions || questions.length === 0) {
    throw new Error("No questions provided for SCORM export");
  }

  try {
    // Generate package files
    const files = await generateScormPackageFiles(questions, config);

    // Create ZIP file
    const zip = new JSZip();

    // Add all files to ZIP
    Object.entries(files).forEach(([filename, content]) => {
      zip.file(filename, content);
    });

    // Generate ZIP blob
    const blob = await zip.generateAsync({ type: "blob" });

    // Create download link
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;

    // Generate filename with timestamp
    const timestamp = new Date().toISOString().split("T")[0];
    const sanitizedTitle = (config.title || "UE5_Quiz")
      .replace(/[^a-z0-9]/gi, "_")
      .toLowerCase();
    link.download = `${sanitizedTitle}_${timestamp}_scorm12.zip`;

    // Trigger download
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    // Clean up
    URL.revokeObjectURL(url);

    return {
      success: true,
      filename: link.download,
      questionCount: questions.length,
    };
  } catch (error) {
    console.error("SCORM export failed:", error);
    throw new Error(`Failed to generate SCORM package: ${error.message}`);
  }
}

/**
 * Validate questions before export
 * @param {Array} questions - Questions to validate
 * @returns {Object} Validation result
 */
export function validateQuestionsForExport(questions) {
  const errors = [];
  const warnings = [];

  if (!questions || questions.length === 0) {
    errors.push("No questions selected for export");
    return { valid: false, errors, warnings };
  }

  if (questions.length < 5) {
    warnings.push(
      "Less than 5 questions selected. Consider adding more for a comprehensive assessment."
    );
  }

  if (questions.length > 100) {
    warnings.push(
      "More than 100 questions selected. Large packages may take longer to load in the LMS."
    );
  }

  questions.forEach((q, index) => {
    if (!q.questionText || q.questionText.trim() === "") {
      errors.push(`Question ${index + 1}: Missing question text`);
    }

    if (!q.choices || q.choices.length < 2) {
      errors.push(`Question ${index + 1}: Must have at least 2 choices`);
    }

    if (!q.correctAnswer) {
      errors.push(`Question ${index + 1}: Missing correct answer`);
    }

    if (q.choices && !q.choices.includes(q.correctAnswer)) {
      errors.push(`Question ${index + 1}: Correct answer not found in choices`);
    }
  });

  return {
    valid: errors.length === 0,
    errors,
    warnings,
    questionCount: questions.length,
  };
}

/**
 * Answer Validator - Validates that the correct answer matches the source excerpt
 * Checks if key terms from the correct answer appear in the SourceExcerpt
 */

/**
 * Extract key terms from text (removes common words)
 * @param {string} text - Text to extract terms from
 * @returns {string[]} Array of key terms
 */
function extractKeyTerms(text) {
    if (!text) return [];

    // Common words to ignore
    const stopWords = new Set([
        'a', 'an', 'the', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
        'have', 'has', 'had', 'do', 'does', 'did', 'will', 'would', 'could',
        'should', 'may', 'might', 'must', 'shall', 'can', 'need', 'dare',
        'to', 'of', 'in', 'for', 'on', 'with', 'at', 'by', 'from', 'as',
        'into', 'through', 'during', 'before', 'after', 'above', 'below',
        'between', 'under', 'again', 'further', 'then', 'once', 'here',
        'there', 'when', 'where', 'why', 'how', 'all', 'each', 'few', 'more',
        'most', 'other', 'some', 'such', 'no', 'not', 'only', 'own', 'same',
        'so', 'than', 'too', 'very', 'just', 'and', 'but', 'or', 'because',
        'until', 'while', 'although', 'this', 'that', 'these', 'those',
        'used', 'use', 'using', 'uses', 'which', 'what', 'it', 'its'
    ]);

    // Extract words, normalize, filter
    const words = text
        .toLowerCase()
        .replace(/<[^>]+>/g, '') // Remove HTML tags
        .replace(/[^a-z0-9\s]/g, ' ') // Remove special chars
        .split(/\s+/)
        .filter(word => word.length > 2 && !stopWords.has(word));

    return [...new Set(words)]; // Remove duplicates
}

/**
 * Validates that the correct answer matches the source excerpt
 * @param {Object} question - Question object
 * @returns {{ isValid: boolean, confidence: number, warning: string | null, details: Object }}
 */
export function validateAnswer(question) {
    // Get the correct answer based on CorrectLetter
    const correctLetter = question.CorrectLetter || question.correctLetter;
    const sourceExcerpt = question.SourceExcerpt || question.sourceExcerpt;

    if (!correctLetter || !sourceExcerpt) {
        return {
            isValid: false,
            confidence: 0,
            warning: 'Missing CorrectLetter or SourceExcerpt',
            details: {
                correctLetter: correctLetter || null,
                hasExcerpt: !!sourceExcerpt
            }
        };
    }

    // Get the correct answer text
    const letterToOption = {
        'A': question.OptionA || question.optionA,
        'B': question.OptionB || question.optionB,
        'C': question.OptionC || question.optionC,
        'D': question.OptionD || question.optionD
    };

    const correctAnswer = letterToOption[correctLetter.toUpperCase()];

    if (!correctAnswer) {
        return {
            isValid: false,
            confidence: 0,
            warning: `No option found for letter ${correctLetter}`,
            details: { correctLetter, options: letterToOption }
        };
    }

    // Extract key terms from both
    const answerTerms = extractKeyTerms(correctAnswer);
    const excerptText = sourceExcerpt.toLowerCase();

    // Count how many answer terms appear in excerpt
    let matchedTerms = 0;
    const matchedKeyTerms = [];

    for (const term of answerTerms) {
        if (excerptText.includes(term)) {
            matchedTerms++;
            matchedKeyTerms.push(term);
        }
    }

    // Calculate confidence
    const matchRatio = answerTerms.length > 0 ? matchedTerms / answerTerms.length : 0;
    const confidence = Math.round(matchRatio * 100);

    // Determine validity
    let isValid = confidence >= 50;
    let warning = null;

    if (confidence < 30) {
        warning = `Answer "${correctAnswer}" not found in source excerpt`;
        isValid = false;
    } else if (confidence < 50) {
        warning = `Low confidence: only ${matchedTerms}/${answerTerms.length} key terms matched`;
    } else if (confidence < 70) {
        warning = `Moderate confidence: verify answer matches source`;
    }

    return {
        isValid,
        confidence,
        warning,
        details: {
            correctAnswer,
            correctLetter,
            answerTerms,
            matchedTerms: matchedKeyTerms,
            totalTerms: answerTerms.length
        }
    };
}

/**
 * Batch validate answers
 * @param {Array} questions - Array of question objects
 * @returns {Array} Questions with answerValidation field added
 */
export function validateAnswersBatch(questions) {
    return questions.map(q => ({
        ...q,
        answerValidation: validateAnswer(q)
    }));
}

export default validateAnswer;

/**
 * Bulk Delete "deleted" Questions from Firestore
 *
 * This script permanently removes all questions with status: "deleted"
 * Run this in the browser console (F12) when signed in as admin
 */

import { db } from "./src/services/firebase.js";
import {
  collection,
  query,
  where,
  getDocs,
  deleteDoc,
  doc,
} from "firebase/firestore";

export async function bulkDeleteSoftDeleted(discipline = null, dryRun = true) {
  console.log("≡ƒùæ∩╕Å Bulk Delete Script Starting...");
  console.log(`Mode: ${dryRun ? "DRY RUN" : "LIVE DELETE"}`);

  try {
    // Query for all "deleted" questions
    const questionsRef = collection(db, "questions");
    let q = query(questionsRef, where("status", "==", "deleted"));

    // Optionally filter by discipline
    if (discipline) {
      q = query(
        questionsRef,
        where("status", "==", "deleted"),
        where("discipline", "==", discipline)
      );
      console.log(`≡ƒôì Filtering by discipline: ${discipline}`);
    }

    const snapshot = await getDocs(q);
    console.log(`≡ƒôè Found ${snapshot.size} questions with status "deleted"`);

    if (snapshot.size === 0) {
      console.log("Γ£à No deleted questions found. Database is clean!");
      return { success: true, deleted: 0 };
    }

    // Show preview
    console.log("\n≡ƒôï Preview of questions to delete:");
    snapshot.docs.slice(0, 10).forEach((doc) => {
      const q = doc.data();
      console.log(
        `- ${doc.id} | ${q.discipline} | ${q.question?.substring(0, 60)}...`
      );
    });

    if (snapshot.size > 10) {
      console.log(`... and ${snapshot.size - 10} more`);
    }

    if (dryRun) {
      console.log("\nΓÜá∩╕Å DRY RUN MODE - No questions were deleted");
      console.log(
        "To actually delete, run: bulkDeleteSoftDeleted(null, false)"
      );
      return { success: true, deleted: 0, dryRun: true };
    }

    // Confirm before deletion
    console.log(
      "\nΓÜá∩╕Å LIVE DELETE MODE - About to permanently delete questions"
    );
    console.log("Deleting in 3 seconds... Press Ctrl+C to cancel");
    await new Promise((resolve) => setTimeout(resolve, 3000));

    // Delete all
    const deletePromises = snapshot.docs.map((doc) => deleteDoc(doc.ref));
    await Promise.all(deletePromises);

    console.log(
      `Γ£à Successfully deleted ${snapshot.size} questions from Firestore`
    );
    console.log("≡ƒÆí Refresh the page to see the updated counts");

    return {
      success: true,
      deleted: snapshot.size,
      discipline: discipline,
    };
  } catch (error) {
    console.error("Γ¥î Bulk delete failed:", error);
    return {
      success: false,
      error: error.message,
    };
  }
}

