                reviewerName: cols[15] || "",
                status: 'accepted',
                language: cols[16] || fileLanguage || "English"
            };
        }
        importedQuestions.push(qObj);
    });

    return importedQuestions;
};

/**
 * Reads a file and returns its content as a promise.
 * @param {File} file - The file to read.
 * @returns {Promise<string>} - The file content.
 */
export const readFileContent = (file) => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (ev) => resolve(ev.target.result);
        reader.onerror = (err) => reject(err);
        reader.readAsText(file);
    });
};

/**
 * Processes a single uploaded file.
 * Validates, reads, and parses the file based on its type.
 * @param {File} file - The file to process.
 * @param {string} creatorName - The current creator name from config.
 * @returns {Promise<Object>} - Result object { type: 'questions'|'reference', data: ..., error: ... }
 */
export const processUploadedFile = async (file, creatorName) => {
    // 1. Basic File Validation
    const fileValidation = validateFile(file);
    if (!fileValidation.isValid) {
        return { error: fileValidation.error };
    }

    try {
        const content = await readFileContent(file);

        // 2. CSV Specific Processing
        if (file.name.toLowerCase().endsWith('.csv')) {
            const contentValidation = validateCSVContent(content);
            if (!contentValidation.isValid) {
                return { error: `Invalid CSV content: ${contentValidation.error}` };
            }

            const questions = parseCSVQuestions(content, file.name, creatorName);
            if (questions.length === 0) {
                // If it was a CSV but returned no questions, it might be a reference file or invalid format
                // For now, let's treat it as a reference file if it failed parsing as questions but is valid text
                return { type: 'reference', data: { name: file.name, content, size: file.size } };
            }

            return { type: 'questions', data: questions, language: questions[0].language };
        }

        // 3. Other Text Files (Reference)
        return { type: 'reference', data: { name: file.name, content, size: file.size } };

    } catch (err) {
        return { error: `Failed to read file: ${err.message}` };
    }
};

/**
 * Migration Script: Link Existing Translations with Original Questions
 *
 * This script fixes existing translations in the database by ensuring:
 * 1. All English originals have a uniqueId
 * 2. All translations share the same uniqueId as their original
 * 3. Both can be found by createUniqueFilteredQuestions for language switching
 */

import { db } from "../services/firebase.js";
import { collection, getDocs, doc, updateDoc } from "firebase/firestore";

async function migrateTranslations() {
  console.log("≡ƒöä Starting translation migration...");

  try {
    // 1. Fetch all questions from Firestore
    const questionsRef = collection(db, "questions");
    const snapshot = await getDocs(questionsRef);
    const allQuestions = snapshot.docs.map((doc) => ({
      firestoreId: doc.id,
      ...doc.data(),
    }));

    console.log(`≡ƒôè Found ${allQuestions.length} total questions`);

    // 2. Group questions by their content similarity (same question text = same original)
    const _translationGroups = new Map();

    // Find all non-English questions (translations)
    const translations = allQuestions.filter(
      (q) => q.language && q.language !== "English"
    );

    console.log(`≡ƒîì Found ${translations.length} translated questions`);

    // 3. For each translation, find its English original
    let fixedCount = 0;
    let alreadyLinkedCount = 0;

    for (const translation of translations) {
      // Skip if already has a uniqueId (already linked)
      if (translation.uniqueId) {
        alreadyLinkedCount++;

        // Check if the English original also has this uniqueId
        const englishOriginal = allQuestions.find(
          (q) =>
            q.uniqueId === translation.uniqueId &&
            (q.language === "English" || !q.language)
        );

        if (!englishOriginal) {
          console.warn(
            `ΓÜá∩╕Å Translation has uniqueId but no English original found:`,
            {
              id: translation.id,
              uniqueId: translation.uniqueId,
              language: translation.language,
            }
          );
        }
        continue;
      }

      // Find English original by matching discipline, type, difficulty, and similar question structure
      const englishOriginal = allQuestions.find(
        (q) =>
          (q.language === "English" || !q.language) &&
          q.discipline === translation.discipline &&
          q.type === translation.type &&
          q.difficulty === translation.difficulty &&
          q.correct === translation.correct // Same correct answer
      );

      if (englishOriginal) {
        // Generate or use existing uniqueId
        const sharedUniqueId = englishOriginal.uniqueId || crypto.randomUUID();

        console.log(`≡ƒöù Linking translation to original:`, {
          originalId: englishOriginal.id,
          translationId: translation.id,
          translationLanguage: translation.language,
          sharedUniqueId,
        });

        // Update English original if it doesn't have uniqueId
        if (!englishOriginal.uniqueId) {
          await updateDoc(doc(db, "questions", englishOriginal.firestoreId), {
            uniqueId: sharedUniqueId,
            language: "English", // Ensure language is set
          });
          console.log(`  Γ£à Updated English original with uniqueId`);
        }

        // Update translation with uniqueId
        await updateDoc(doc(db, "questions", translation.firestoreId), {
          uniqueId: sharedUniqueId,
        });
        console.log(`  Γ£à Updated translation with uniqueId`);

        fixedCount++;
      } else {
        console.warn(`ΓÜá∩╕Å No English original found for translation:`, {
          id: translation.id,
          language: translation.language,
          discipline: translation.discipline,
        });
      }
    }

    console.log("\nΓ£à Migration complete!");
    console.log(`≡ƒôè Statistics:`);
    console.log(`   - Already linked: ${alreadyLinkedCount}`);
    console.log(`   - Newly linked: ${fixedCount}`);
    console.log(`   - Total translations: ${translations.length}`);
  } catch (error) {
    console.error("Γ¥î Migration failed:", error);
    throw error;
  }
}

