export const downloadFile = (data, filename) => {
  const BOM = "\uFEFF";
  const finalType = "text/csv;charset=utf-8;";
  const blob = new Blob([BOM + data], { type: finalType });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

import { validateURL } from './urlValidator';
import { validateAnswer } from './answerValidator';

/**
 * Unified Question Validator
 * Checks for:
 * 1. Critical failures (Auto-reject):
 *    - Missing source URL
 *    - Invalid URL pattern
 *    - Missing source excerpt
 *    - Excerpt too short (< 20 chars)
 * 
 * 2. Warnings (Flag for review):
 *    - Answer doesn't match source excerpt (low confidence)
 *    - URL missing "-in-unreal-engine" suffix (medium confidence)
 * 
 * @param {Object} question - The question object to validate
 * @returns {{ 
 *   isValid: boolean, 
 *   isCriticalFailure: boolean, 
 *   confidence: number, 
 *   warnings: string[], 
 *   details: Object 
 * }}
 */
export function validateQuestion(question) {
    const warnings = [];
    let isCriticalFailure = false;
    let overallConfidence = 100;

    // 1. Validate Source URL (Critical usually, but allowed if empty)
    const urlResult = validateURL(question.SourceURL || question.sourceUrl);
    if (!urlResult.isValid) {
        if (urlResult.warning === 'Missing documentation URL') {
            // Soft failure: Allow empty URL if unsure (prompt instruction), but flag it
            warnings.push('Warning: Missing documentation URL');
            overallConfidence = Math.min(overallConfidence, 50);
        } else {
            // Hard failure: Invalid domain, disallowed pattern, etc.
            isCriticalFailure = true;
            warnings.push(`Critical: ${urlResult.warning}`);
        }
    } else if (urlResult.warning) {
        warnings.push(urlResult.warning);
        overallConfidence = Math.min(overallConfidence, urlResult.confidence);
    }

    // 2. Validate Source Excerpt (Critical)
    const excerpt = question.SourceExcerpt || question.sourceExcerpt;
    if (!excerpt || typeof excerpt !== 'string') {
        isCriticalFailure = true;
        warnings.push('Critical: Missing source excerpt');
    } else if (excerpt.length < 20) {
        isCriticalFailure = true;
        warnings.push(`Critical: Source excerpt too short ("${excerpt}")`);
    } else if (/^\d+$/.test(excerpt.trim())) {
        // Catch cases where excerpt is just a number (like "100")
        isCriticalFailure = true;
        warnings.push(`Critical: Invalid source excerpt ("${excerpt}")`);
    }

    // 3. Validate Answer Match (Warning)
    // Only run if we have a valid excerpt
    let answerResult = { confidence: 100, warning: null };
    if (!isCriticalFailure) {
        answerResult = validateAnswer(question);
        if (!answerResult.isValid) {
            // If answer validation fails completely (e.g. < 30% match), treat as severe warning but not critical auto-reject yet
            // User requested to flag these, not auto-reject
            warnings.push(answerResult.warning);
            overallConfidence = Math.min(overallConfidence, answerResult.confidence);
        } else if (answerResult.warning) {
            warnings.push(answerResult.warning);
            overallConfidence = Math.min(overallConfidence, answerResult.confidence);
        }
    }

    return {
        isValid: !isCriticalFailure,
        isCriticalFailure,
        confidence: overallConfidence,
        warnings,
        details: {
            url: urlResult,
            answer: answerResult
        }
    };
}

/**
 * Batch validate questions
 * @param {Array} questions 
 * @returns {Array} Questions with validation metadata attached
 */
export function validateQuestionsBatch(questions) {
    return questions.map(q => {
        const validation = validateQuestion(q);
        return {
            ...q,
            _validation: validation
        };
    });
}

/**
 * Utility functions for quiz GUID generation and seeded randomization
 */

/**
 * Generate a UUID v4 GUID
 * @returns {string} GUID in format: xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx
 */
export function generateGUID() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

/**
 * Simple hash function to convert string to number
 * @param {string} str - String to hash
 * @returns {number} Hash value
 */
function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash = hash & hash; // Convert to 32bit integer
  }
  return Math.abs(hash);
}

/**
 * Create a seeded random number generator
 * Uses a simple Linear Congruential Generator (LCG)
 * @param {string} seed - String seed (e.g., GUID)
 * @returns {Function} Random function that returns 0-1
 */
export function createSeededRandom(seed) {
  let state = hashString(seed);

  return function () {
    // LCG using GCC's constants
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

/**
 * Shuffle an array using a seeded random function
 * Fisher-Yates shuffle with custom RNG
 * @param {Array} array - Array to shuffle
 * @param {Function} randomFn - Seeded random function
 * @returns {Array} Shuffled copy of array
 */
export function seededShuffle(array, randomFn) {
  const copy = [...array];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(randomFn() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

/**
 * Report quiz results to SCORM LMS
 * @param {Object} results - Quiz results
 * @param {string} quizGuid - Quiz instance GUID
 * @param {number} timeSpent - Time spent in seconds
 */
export function reportToSCORM(results, quizGuid, timeSpent) {
  if (typeof window.SCORM12 === "undefined" || !window.SCORM12.isConnected()) {
    console.log("SCORM not available - results not sent to LMS");
    console.log("Quiz GUID:", quizGuid);
    console.log("Results:", results);
    return;
  }

  try {
    // Send score
    window.SCORM12.setScoreRaw(results.percentage, 0, 100);

    // Send pass/fail status
    window.SCORM12.setStatus(results.passed ? "passed" : "failed");

    // Send session time
    window.SCORM12.setSessionTimeSeconds(timeSpent);

    // Send quiz GUID as suspend data for debugging
    // SCORM 1.2 allows up to 4096 characters in suspend_data
    const suspendData = JSON.stringify({
      quizGuid,
      completedAt: new Date().toISOString(),
      score: results.percentage,
      correct: results.correct,
      total: results.total,
    });

    window.SCORM12.setValue("cmi.suspend_data", suspendData);

    // Commit all changes
    window.SCORM12.commit();

    console.log("Quiz results sent to SCORM LMS");
    console.log("Quiz GUID:", quizGuid);
  } catch (error) {
    console.error("Failed to report to SCORM:", error);
  }
}

import DOMPurify from "dompurify";

export const chunkArray = (array, size) => {
  const result = [];
  for (let i = 0; i < array.length; i += size) {
    result.push(array.slice(i, i + size));
  }
  return result;
};

/**
 * Calculate text similarity using Levenshtein distance (0-1 score)
 * @param {string} str1 - First string to compare
 * @param {string} str2 - Second string to compare
 * @returns {number} Similarity score between 0 (different) and 1 (identical)
 */
export const textSimilarity = (str1, str2) => {
  if (!str1 || !str2) return 0;

  // Normalize: lowercase, remove extra whitespace, remove HTML tags
  const normalize = (s) =>
    s
      .toLowerCase()
      .replace(/<[^>]*>/g, "")
      .replace(/\s+/g, " ")
      .trim();
  const a = normalize(str1);
  const b = normalize(str2);

  if (a === b) return 1;
  if (a.length === 0 || b.length === 0) return 0;

  // For very long strings, use a simpler word-based comparison for performance
  if (a.length > 500 || b.length > 500) {
    const wordsA = new Set(a.split(" "));
    const wordsB = new Set(b.split(" "));
    const intersection = [...wordsA].filter((w) => wordsB.has(w)).length;
    const union = new Set([...wordsA, ...wordsB]).size;
    return union > 0 ? intersection / union : 0;
  }

  // Levenshtein distance calculation
  const matrix = Array(b.length + 1)
    .fill(null)
    .map(() => Array(a.length + 1).fill(null));

  for (let i = 0; i <= a.length; i++) matrix[0][i] = i;
  for (let j = 0; j <= b.length; j++) matrix[j][0] = j;

  for (let j = 1; j <= b.length; j++) {
    for (let i = 1; i <= a.length; i++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      matrix[j][i] = Math.min(
        matrix[j][i - 1] + 1, // deletion
        matrix[j - 1][i] + 1, // insertion
        matrix[j - 1][i - 1] + cost // substitution
      );
    }
  }

  const maxLen = Math.max(a.length, b.length);
  return 1 - matrix[b.length][a.length] / maxLen;
};

/**
 * Compute word-level diff between two strings for inline highlighting
 * Uses Longest Common Subsequence (LCS) algorithm for accurate diff
 * @param {string} oldText - Original text
 * @param {string} newText - New/modified text
 * @returns {Array<{type: 'unchanged'|'removed'|'added', text: string}>} Array of diff segments
 */
export const computeWordDiff = (oldText, newText) => {
  if (!oldText && !newText) return [];
  if (!oldText) return [{ type: "added", text: newText }];
  if (!newText) return [{ type: "removed", text: oldText }];
  if (oldText === newText) return [{ type: "unchanged", text: oldText }];

  // Tokenize into words (preserving punctuation attached to words)
  const tokenize = (text) => text.split(/(\s+)/).filter((t) => t.length > 0);

  const oldTokens = tokenize(oldText);
  const newTokens = tokenize(newText);

  // Build LCS table
  const m = oldTokens.length;
  const n = newTokens.length;
  const dp = Array(m + 1)
    .fill(null)
    .map(() => Array(n + 1).fill(0));

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (oldTokens[i - 1] === newTokens[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // Backtrack to find the diff
  let i = m,
    j = n;

  const tempDiff = [];
  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && oldTokens[i - 1] === newTokens[j - 1]) {
      tempDiff.unshift({ type: "unchanged", text: oldTokens[i - 1] });
      i--;
      j--;
    } else if (j > 0 && (i === 0 || dp[i][j - 1] >= dp[i - 1][j])) {
      tempDiff.unshift({ type: "added", text: newTokens[j - 1] });
      j--;
    } else {
      tempDiff.unshift({ type: "removed", text: oldTokens[i - 1] });
      i--;
    }
  }

  // Merge consecutive segments of the same type for cleaner output
  const merged = [];
  for (const segment of tempDiff) {
    if (merged.length > 0 && merged[merged.length - 1].type === segment.type) {
      merged[merged.length - 1].text += segment.text;
    } else {
      merged.push({ ...segment });
    }
  }

  return merged;
};

export const renderMarkdown = (t) => {
  if (!t) return "";

  // Step 1: Convert markdown-style formatting to HTML
  const html = String(t)
    // Headers
    .replace(
      /^### (.*$)/gim,
      '<h3 class="text-orange-400 font-bold text-xs mt-3 mb-1 uppercase tracking-wide">$1</h3>'
    )
    .replace(
      /^#### (.*$)/gim,
      '<h4 class="text-slate-200 font-bold text-[10px] mt-2 mb-1 uppercase">$1</h4>'
    )
    // Bold (**text**)
    .replace(
      /\*\*(.*?)\*\*/g,
      '<strong class="text-orange-300 font-bold">$1</strong>'
    )
    // Inline code (`code`)
    .replace(
      /`([^`]+)`/g,
      '<code class="px-1.5 py-0.5 rounded bg-blue-950/50 text-blue-300 font-mono text-[0.9em] border border-blue-900/50">$1</code>'
    )
    // Lists
    .replace(
      /^\s*\* (.*$)/gim,
      '<div class="ml-3 flex items-start gap-2"><span class="text-orange-500 mt-1 text-[10px] flex-shrink-0">ΓÇó</span><span>$1</span></div>'
    )
    // Italics (*text*)
    .replace(/\*([^\n*]+)\*/g, '<em class="text-slate-300 italic">$1</em>')
    // Double newlines
    .replace(/\n\s*\n/g, '<div class="h-2"></div>')
    // Single newlines
    .replace(/\n/g, "<br />");

  // Step 2: Sanitize with DOMPurify to prevent XSS
  const sanitized = DOMPurify.sanitize(html, {
    ALLOWED_TAGS: [
      "b",
      "i",
      "em",
      "strong",
      "code",
      "br",
      "div",
      "span",
      "h3",
      "h4",
      "h5",
      "h6",
      "ul",
      "ol",
      "li",
      "p",
    ],
    ALLOWED_ATTR: ["class"],
    ALLOW_DATA_ATTR: false,
  });

  return sanitized;
};

export const sanitizeText = (text) => renderMarkdown(text);

export const stripHtmlTags = (text) => {
  if (typeof text !== "string") return text;
  // Use DOMParser for safer HTML parsing (avoids XSS via innerHTML)
  const parser = new DOMParser();
  const doc = parser.parseFromString(text, "text/html");
  return doc.body.textContent || "";
};

export const safe = (t) => {
  if (t === null || t === undefined) return '""';
  const str = String(t);
  let content = stripHtmlTags(str);
  content = (content || "").trim();
  content = content
    .replace(/[\u200B\uFEFF\u00A0]/g, " ")
    .replace(/\s\s+/g, " ")
    .trim();
  content = content.replace(/(\r\n|\n|\r|\t)/gm, " ");
  content = content.replace(/['"]/g, "");
  const escaped = content.replace(/"/g, '""');
  return `"${escaped}"`;
};

export const parseCSVLine = (text) => {
  const result = [];
  let cell = "";
  let insideQuote = false;
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (char === '"') {
      if (insideQuote && text[i + 1] === '"') {
        cell += '"';
        i++;
      } else {
        insideQuote = !insideQuote;
      }
    } else if (char === "," && !insideQuote) {
      result.push(cell);
      cell = "";
    } else {
      cell += char;
    }
  }
  result.push(cell);
  return result;
};

/**
 * Tutorial analytics and telemetry
 *
 * Tracks tutorial usage, completion, and user behavior to help improve
 * the tutorial experience and identify where users need help.
 */

const TUTORIAL_EVENTS = {
  STARTED: "tutorial_started",
  STEP_CHANGED: "tutorial_step_changed",
  COMPLETED: "tutorial_completed",
  SKIPPED: "tutorial_skipped",
  ELEMENT_NOT_FOUND: "tutorial_element_not_found",
  STEP_SKIPPED: "tutorial_step_skipped",
  ERROR: "tutorial_error",
};

/**
 * Log a tutorial event
 * @param {string} eventName - Event name from TUTORIAL_EVENTS
 * @param {Object} payload - Event data
 * @param {string} payload.scenarioId - Tutorial scenario ID
 * @param {string} [payload.stepId] - Current step ID
 * @param {number} [payload.stepIndex] - Current step index
 * @param {string} [payload.reason] - Reason for event (e.g., 'element_not_found')
 */
export const logTutorialEvent = (eventName, payload) => {
  const event = {
    event: eventName,
    timestamp: new Date().toISOString(),
    ...payload,
  };

  // Console logging for development
  if (import.meta.env.DEV) {
    console.log("[Tutorial Analytics]", event);
  }

  // TODO: Wire into Firestore or analytics service
  // Example: analytics.logEvent(eventName, payload);
  // For now, we'll use localStorage for debugging

  try {
    const key = "ue5_tutorial_events";
    const existing = JSON.parse(localStorage.getItem(key) || "[]");
    existing.push(event);

    // Keep only last 100 events to avoid localStorage bloat
    if (existing.length > 100) {
      existing.shift();
    }

    localStorage.setItem(key, JSON.stringify(existing));
  } catch (error) {
    // Silently fail if localStorage is unavailable
    console.warn("Failed to log tutorial event:", error);
  }
};

/**
 * Get all logged tutorial events
 * @returns {Array<Object>} Array of tutorial events
 */
export const getTutorialEvents = () => {
  try {
    const key = "ue5_tutorial_events";
    return JSON.parse(localStorage.getItem(key) || "[]");
  } catch {
    return [];
  }
};

/**
 * Clear all tutorial events
 */
export const clearTutorialEvents = () => {
  try {
    localStorage.removeItem("ue5_tutorial_events");
  } catch (error) {
    console.warn("Failed to clear tutorial events:", error);
  }
};

/**
 * Get tutorial completion statistics
 * @returns {Object} Statistics object
 */
export const getTutorialStats = () => {
  const events = getTutorialEvents();

  const stats = {
    totalStarts: events.filter((e) => e.event === TUTORIAL_EVENTS.STARTED)
      .length,
    totalCompletions: events.filter(
      (e) => e.event === TUTORIAL_EVENTS.COMPLETED
    ).length,
    totalSkips: events.filter((e) => e.event === TUTORIAL_EVENTS.SKIPPED)
      .length,
    elementNotFoundCount: events.filter(
      (e) => e.event === TUTORIAL_EVENTS.ELEMENT_NOT_FOUND
    ).length,
    byScenario: {},
  };

  // Group by scenario
  events.forEach((event) => {
    if (event.scenarioId) {
      if (!stats.byScenario[event.scenarioId]) {
        stats.byScenario[event.scenarioId] = {
          starts: 0,
          completions: 0,
          skips: 0,
        };
      }

      if (event.event === TUTORIAL_EVENTS.STARTED) {
        stats.byScenario[event.scenarioId].starts++;
      } else if (event.event === TUTORIAL_EVENTS.COMPLETED) {
        stats.byScenario[event.scenarioId].completions++;
      } else if (event.event === TUTORIAL_EVENTS.SKIPPED) {
        stats.byScenario[event.scenarioId].skips++;
      }
    }
  });

  return stats;
};

export { TUTORIAL_EVENTS };
